{"content":"static int vs_history_key_parse(const char *key, unsigned int *seq)
{
  unsigned int value = 0;
  size_t i;

  if (key == NULL || strlen(key) != 8 || key[0] != 'R')
    {
      return -EINVAL;
    }

  for (i = 1; i < 8; i++)
    {
      if (key[i] < '0' || key[i] > '9')
        {
          return -EINVAL;
        }

      value = value * 10u + (unsigned int)(key[i] - '0');
    }

  if (value > VS_HISTORY_SEQ_MAX)
    {
      return -EINVAL;
    }

  if (seq != NULL)
    {
      *seq = value;
    }

  return 0;
}

