static int vs_history_write_all(int fd, const char *text, size_t len)
{
  size_t done = 0;

  while (done < len)
    {
      ssize_t n = write(fd, text + done, len - done);

      if (n < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -errno;
        }

      if (n == 0)
        {
          return -EIO;
        }

      done += (size_t)n;
    }

  return 0;
}

