{"content":"static int vs_history_atomic_write(const char *dir, const char *temporary,
                                   const char *destination,
                                   const char *text)
{
  size_t len = strlen(text);
  int fd;
  int ret;

  fd = open(temporary, O_WRONLY | O_CREAT | O_TRUNC, 0600);
  if (fd < 0)
    {
      return -errno;
    }

  ret = vs_history_write_all(fd, text, len);
  if (ret == 0 && fsync(fd) < 0)
    {
      ret = -errno;
    }

  if (close(fd) < 0 && ret == 0)
    {
      ret = -errno;
    }

  if (ret < 0)
    {
      unlink(temporary);
      return ret;
    }

  if (rename(temporary, destination) < 0)
    {
      ret = -errno;
      unlink(temporary);
      return ret;
    }

  vs_history_sync_dir(dir);
  return 0;
}

