{
  entry->kind = kind;
  snprintf(entry->record_key, sizeof(entry->record_key), VS_HISTORY_KEY_FMT,
           seq);
  entry->date[sizeof(entry->date) - 1] = '\0';
  entry->title[sizeof(entry->title) - 1] = '\0';
  entry->summary[sizeof(entry->summary) - 1] = '\0';
  if (entry->calm > 100)
