      {
        uint8_t index;
        bool matched = false;

        for (index = 0; index < g_social.inflight_count; index++)
          {
            if (strcmp(g_social.inflight[index].msg_id, ev->msg_id) == 0)
              {
                matched = true;
                break;
              }
