{"content":"static int cloud_plain_http(const struct cloud_url_s *url, const char *method,
                            const vela_header_t *headers,
                            const void *body, size_t body_len,
                            char *resp, size_t resp_cap, size_t *resp_len,
                            vela_body_sink_t sink, void *sink_arg)
{
  int attempt;
  int ret = -EIO;

  for (attempt = 0; attempt < 2; attempt++)
    {
      bool reused = false;
      bool reusable = false;
      bool touched = false;
      int sock = cloud_keep_take(url, &reused);

      if (sock < 0)
        {
          return sock;
        }

      ret = cloud_plain_http_once(url, method, headers, body, body_len,
                                  resp, resp_cap, resp_len, sock,
                                  &reusable, &touched, sink, sink_arg);

      if (ret >= 0 && reusable)
        {
          cloud_keep_put(sock, url);
          return ret;
        }

      /* Not held: either it failed, or its body ran to EOF so the socket's
       * position is no longer known.
       */

      if (reused)
        {
          cloud_keep_drop();
        }
      else
        {
          close(sock);
        }

      if (ret >= 0 || !reused || touched)
        {
          return ret;
        }

      /* A held connection that produced nothing.  One more try, on a
       * connection this device just opened.
       */
    }

  return ret;
}

/****************************************************************************
 * Name: cloud_http
 *
 * Description:
 *   Dispatch one exchange to the right transport and normalise the result.
 *   vela_tls.c reports its own error space (VELA_TLS_ERR_*); everything past
 *   this point sees HTTP status codes and negative errnos only.
 *
 ****************************************************************************/

static int cloud_http_ex(const struct cloud_url_s *url, const char *method,
                         const vela_header_t *headers,
                         const void *body, size_t body_len,
                         char *resp, size_t resp_cap, size_t *resp_len,
                         vela_body_sink_t sink, void *sink_arg)
{
  int ret;

  if (!url->tls)
    {
      return cloud_plain_http(url, method, headers, body, body_len,
                              resp, resp_cap, resp_len, sink, sink_arg);
    }

  if (sink != NULL)
    {
      ret = vela_https_request_stream(url->host, url->port, method, url->path,
                                      headers, (const char *)body, body_len,
                                      sink, sink_arg, resp_len);
    }
  else
    {
      ret = vela_https_request(url->host, url->port, method, url->path,
                               headers, (const char *)body, body_len, resp,
                               resp_cap, resp_len);
    }
  if (ret > 0)
    {
      return ret;
    }

  switch (ret)
    {
      case VELA_TLS_ERR_CONNECT:
        return -ECONNREFUSED;

      case VELA_TLS_ERR_HANDSHAKE:
        return -EPROTO;

      case VELA_TLS_ERR_WRITE:
      case VELA_TLS_ERR_READ:
        return -EIO;

      /* Raised when the request header does not fit vela_tls.c's own 4 KiB
       * builder -- not when the response is too large for resp_buf, which
       * that path does not detect at all.  A presigned URL long enough to
       * overflow it is the realistic cause.
       */

      case VELA_TLS_ERR_OVERFLOW:
        return -E2BIG;

      /* The sink refused.  For the download-to-file path that means the file
       * would have outgrown its budget or the write failed, and the sink has
       * already said which; keeping the distinction here lets the caller tell
       * it apart from a transport fault.
       */

      case VELA_TLS_ERR_SINK:
        return -EFBIG;

      case VELA_TLS_ERR_PROTOCOL:
        return -EPROTO;

      default:
        return ret < 0 ? ret : -EIO;
    }
}

/****************************************************************************
 * Name: cloud_http
 *
 * Description:
 *   cloud_http_ex() for the callers that want the body in a buffer, which is
 *   all of them except the download that goes to a file.
 *
 ****************************************************************************/

static int cloud_http(const struct cloud_url_s *url, const char *method,
                      const vela_header_t *headers,
                      const void *body, size_t body_len,
                      char *resp, size_t resp_cap, size_t *resp_len)
{
  return cloud_http_ex(url, method, headers, body, body_len, resp, resp_cap,
                       resp_len, NULL, NULL);
}

/****************************************************************************
 * Name: cloud_api_call
 *
 * Description:
 *   One exchange with a /contest/v1 endpoint on the configured host.
 *   path_and_query is appended to the configured origin, so callers deal in
 *   paths rather than URLs.
 *
 * Returned Value:
 *   HTTP status code, or a negative errno.
 *
 ****************************************************************************/

static int cloud_api_call(const char *method, const char *path_and_query,
                          const char *json_body, char *resp, size_t resp_cap)
{
  struct cloud_url_s *url;
  bool url_psram = false;
  vela_header_t headers[2];
  int ret;

  if (!g_cloud.configured)
    {
      return -ENODATA;
    }

  /* PSRAM first.  struct cloud_url_s is about 3 KB because of its
   * CLOUD_PATH_MAX path member, and this runs on every session, upload
   * registration and getResult call, so it is one of the two allocations the
   * social path asks for per HTTP request.  cloud_get_result_call() has the
   * measurement showing the internal heap cannot be relied on for that size
   * once a session's worker stacks and TLS contexts are live.
   */

  url = cloud_alloc(sizeof(*url), &url_psram);
  if (url == NULL)
    {
      return -ENOMEM;
    }

  memset(url, 0, sizeof(*url));
  url->tls = g_cloud.tls;
  snprintf(url->host, sizeof(url->host), "%s", g_cloud.host);
  snprintf(url->port, sizeof(url->port), "%s", g_cloud.port);

  /* The base path goes on here rather than into the four CLOUD_PATH_*
   * literals, so those keep the document's own spelling and a grep for a path
   * still finds it.  This is also the only place all four endpoints pass
   * through, which is what makes one concatenation enough.
   *
   * No slash is inserted: the prefix is stored with a leading slash and
   * without a trailing one (vp_cloud_path_ok() enforces both), and every
   * path_and_query starts with one.  An empty prefix therefore also works
   * without a special case.
   */

  if (snprintf(url->path, sizeof(url->path), "%s%s", g_cloud.base_path,
               path_and_query) >= (int)sizeof(url->path))
    {
      cloud_free(url, url_psram);
      return -E2BIG;
    }

  headers[0].name = "Content-Type";
  headers[0].value = "application/json";
  headers[1].name = NULL;
  headers[1].value = NULL;

  ret = cloud_http(url, method, headers, json_body,
                   json_body != NULL ? strlen(json_body) : 0,
                   resp, resp_cap, NULL);

  cloud_free(url, url_psram);
  return ret;
}

/****************************************************************************
 * Name: cloud_json_int
 *
 * Description:
 *   Read an integer that may have been sent either as a number or as a
 *   string.  The cloud document does both for the same fields -- msgEvent
 *   appears as 0 in one example and "0" in another -- so accepting only one
 *   form would make the parser depend on which example the server was
 *   written from.
 *
 ****************************************************************************/

static bool cloud_json_int(const cJSON *obj, const char *name, int *out)
{
  const cJSON *item;

  if (obj == NULL)
    {
      return false;
    }

  item = cJSON_GetObjectItem((cJSON *)obj, name);
  if (item == NULL)
    {
      return false;
    }

  if (cJSON_IsNumber(item))
    {
      *out = item->valueint;
      return true;
    }

  if (cJSON_IsString(item) && item->valuestring != NULL)
    {
      char *endp = NULL;
      long v = strtol(item->valuestring, &endp, 10);

      if (endp != item->valuestring)
        {
          *out = (int)v;
          return true;
        }
    }

  return false;
}

/****************************************************************************
 * Name: cloud_json_str
 *
 * Description:
 *   Copy a string member out, truncating on a UTF-8 boundary.  Returns false
 *   when the member is absent or is not a string, leaving dst empty.
 *
 ****************************************************************************/

static bool cloud_json_str(const cJSON *obj, const char *name, char *dst,
                           size_t cap)
{"}

{"content":"   * not a field a user can get right from a phone: turning TLS on against a
   * cloud that only speaks cleartext fails in the handshake, with nothing on
   * the page to explain it, and this board has no CA bundle to make the
   * encrypted case actually authenticated.  See CONFIG_VS_SOCIAL_CLOUD_TLS.
   */

#ifdef CONFIG_VS_SOCIAL_CLOUD_TLS
  tls = true;
#else
  tls = false;
#endif

  /* A Kconfig host, when set, overrides the shared factory default.  This is
   * what makes a build aimed at a local mock work without provisioning: the
   * option existed before the record did, and a build that sets it is asking
   * for that endpoint deliberately.
   */

  if (CONFIG_VS_SOCIAL_CLOUD_HOST[0] != '\0')
    {
      host = CONFIG_VS_SOCIAL_CLOUD_HOST;
      port = (uint16_t)CONFIG_VS_SOCIAL_CLOUD_PORT;
    }

  ret = velasight_provisioning_load(cred);
  if (ret == 0)
    {
      if (cred->cloud_host[0] != '\0')
        {
          host   = cred->cloud_host;
          origin = VS_CLOUD_ORIGIN_PROVISIONED;
        }

      if (cred->cloud_port != 0)
        {
          port   = cred->cloud_port;
          origin = VS_CLOUD_ORIGIN_PROVISIONED;
        }

      /* An empty stored prefix cannot be told from "not set" here, and the
       * two want opposite things: a device deliberately talking to a server
       * that hosts the interface at its root needs the empty value to win.
       *
       * Resolved in favour of the record whenever the record supplied any
       * endpoint field at all.  A user who typed a host and cleared the
       * prefix box asked for exactly that combination; a record that carries
       * no endpoint at all falls through to the default prefix.
       */

      if (origin == VS_CLOUD_ORIGIN_PROVISIONED ||
          cred->cloud_path[0] != '\0')
        {
          path = cred->cloud_path;
          origin = VS_CLOUD_ORIGIN_PROVISIONED;
        }
    }
  else if (ret != -ENOENT)
    {
      /* A corrupt record is not a reason to refuse to run: the default
       * endpoint is a working address.  It is a reason to say so, because the
       * device is now using a different host than the page would show.
       */

      printf("%s: provisioning record unreadable (%d), using default "
             "endpoint\n", CLOUD_TAG, ret);
    }

  changed = cloud_apply_endpoint(host, port, path, tls, origin);
  free(cred);
  return changed;"}

{"content":"int vs_cloud_social_upload(const char *session_id,
                           const struct vs_cloud_media_packet_s *packet,
                           struct vs_cloud_upload_s *out)
{
  char body[224];
  char presigned[CLOUD_PRESIGNED_PATH_MAX];
  char *resp = NULL;
  bool from_psram = false;
  bool url_psram = false;
  cJSON *root = NULL;
  cJSON *value = NULL;
  struct cloud_url_s *url = NULL;
  vela_header_t headers[2];
  int status = 0;
  int http;
  int ret;

  if (session_id == NULL || packet == NULL || out == NULL ||
      packet->data == NULL || packet->len == 0)
    {
      return -EINVAL;
    }

  if (!g_cloud.configured)
    {
      return -ENODATA;
    }

  if (!cloud_id_valid(session_id, VS_CLOUD_SESSION_ID_MAX))
    {
      return -EINVAL;
    }

  memset(out, 0, sizeof(*out));

  /* Step one: register.  event is the reserved outer event type (emotion
   * recognition); msgEvent says which kind of file this is.
   */

  snprintf(body, sizeof(body),
           "{\"event\":%d,\"msgEvent\":%d,\"deviceId\":\"%s\","
           "\"sessionId\":\"%s\",\"timestamp\":\"%llu\"}",
           VS_CLOUD_EVENT_EMOTION,
           packet->type == VS_CLOUD_MEDIA_AUDIO ? VS_CLOUD_MEDIA_AUDIO
                                                : VS_CLOUD_MEDIA_IMAGE,
           vs_cloud_device_id(), session_id,
           (unsigned long long)cloud_now_ms());

  resp = cloud_alloc(CONFIG_VS_SOCIAL_REG_RESP_BYTES, &from_psram);
  if (resp == NULL)
    {
      return -ENOMEM;
    }

  http = cloud_api_call("POST", CLOUD_PATH_UPLOAD, body, resp,
                        CONFIG_VS_SOCIAL_REG_RESP_BYTES);
  if (http < 0)
    {
      ret = http;
      goto out;
    }

  if (http < 200 || http >= 300)
    {
      printf("%s: upload register returned HTTP %d\n", CLOUD_TAG, http);
      ret = -EIO;
      goto out;
    }

  root = cJSON_Parse(resp);
  ret = cloud_check_envelope(root, session_id, &status, &value);
  if (ret < 0)
    {
      goto out;
    }

  /* 10 (image accepted) and 11 (audio accepted) are the documented success
   * codes; 0 is what the document's own response example shows for the same
   * case, so all three are accepted.  30 is the only failure.
   *
   * 30 comes back as -ENOTCONN rather than -EIO, because the caller has to be
   * able to tell it apart.  Everything else that fails here is per-item and
   * worth another try: a timed-out connect, a malformed reply, an HTTP error.
   * A 30 is the cloud saying it has no session to attach the message to --
   * "session not found or closed", measured continuously through a 2026-08-31
   * session -- and asking again with the same sessionId cannot change that
   * answer.  The cloud interface document's own known-issues section explains
   * why it happens: two server instances behind a 50/50 balancer with session
   * state held locally, so the instance that answers may never have seen the
   * open.  Retrying still costs a full TLS round trip per attempt, which is
   * exactly the bill this split exists to stop paying.
   */

  if (status != 0 && status != 10 && status != 11)
    {
      char log[VS_TEXT_SHORT];

      cloud_value_log(value, root, log, sizeof(log));
      printf("%s: upload refused, status %d%s%s\n", CLOUD_TAG, status,
             log[0] != '\0' ? ": " : "", log);
      ret = status == 30 ? -ENOTCONN : -EIO;
      goto out;
    }

  if (!cloud_json_exact(value, "msgId", out->msg_id, sizeof(out->msg_id)) ||
      !cloud_id_valid(out->msg_id, sizeof(out->msg_id)))
    {
      printf("%s: upload response has no usable msgId\n", CLOUD_TAG);
      ret = -EPROTO;
      goto out;
    }

  if (!cloud_json_exact(value, "presignedUrl", presigned,
                        sizeof(presigned)))
    {
      printf("%s: upload response has no presignedUrl\n", CLOUD_TAG);
      ret = -EPROTO;
      goto out;
    }

  /* Step two: the bytes.  A bare PUT -- no multipart framing, which is what
   * the registration-plus-presigned-URL shape means.
   *
   * PSRAM first, like resp above.  struct cloud_url_s carries a
   * CLOUD_PATH_MAX path, which puts it around 3 KB, and the internal heap is
   * the wrong pool to ask for that during a session -- see
   * cloud_get_result_call() for the measurement that motivated this.
   */

  url = cloud_alloc(sizeof(*url), &url_psram);
  if (url == NULL)
    {
      ret = -ENOMEM;
      goto out;
    }

  ret = cloud_url_parse(presigned, url);
  if (ret == -EPROTONOSUPPORT)
    {
      /* The cloud's mock mode answers with "mock://...".  Registration
       * succeeded and the msgId is still worth polling, so this is reported
       * through payload_sent rather than as a failure.
       */

      if (!g_cloud.mock_url_logged)
        {
          g_cloud.mock_url_logged = true;
          printf("%s: presigned URL %s has no transferable scheme; "
                 "registering only (mock cloud)\n", CLOUD_TAG, presigned);
        }

      out->payload_sent = false;
      ret = 0;
      goto out;
    }

  if (ret < 0)
    {
      printf("%s: presigned URL rejected: %d\n", CLOUD_TAG, ret);
      goto out;
    }

  headers[0].name = "Content-Type";
  headers[0].value = packet->type == VS_CLOUD_MEDIA_AUDIO ? "audio/ogg"
                                                          : "image/jpeg";
  headers[1].name = NULL;
  headers[1].value = NULL;

  http = cloud_http(url, "PUT", CLOUD_UPLOAD_SEND_CT ? headers : NULL,
                    packet->data, packet->len, resp,
                    CONFIG_VS_SOCIAL_REG_RESP_BYTES, NULL);
  if (http < 0)
    {
      printf("%s: %s transfer failed: %d\n", CLOUD_TAG,
             packet->type == VS_CLOUD_MEDIA_AUDIO ? "audio" : "image", http);
      ret = http;
      goto out;
    }

  if (http < 200 || http >= 300)
    {
      /* Object stores answer 403 when the signature did not cover exactly the
       * headers that were sent, which is the failure
       * CONFIG_VS_SOCIAL_UPLOAD_CONTENT_TYPE exists to let you flip without
       * a code change.  Worth naming, because the response body is usually
       * XML nobody reads.
       */

      /* The store's reply is sitting in resp and is the only thing that says
       * which of the two signing mismatches happened, so print the head of
       * it.  Bounded and on one line: it is XML, and the useful part is the
       * <Code> element near the front.
       */

      printf("%s: %s transfer returned HTTP %d%s: %.160s\n", CLOUD_TAG,
             packet->type == VS_CLOUD_MEDIA_AUDIO ? "audio" : "image", http,
             http == 403 ? " (check VS_SOCIAL_UPLOAD_CONTENT_TYPE)" : "",
             resp);
      ret = -EIO;
      goto out;
    }

  out->payload_sent = true;
  ret = 0;

out:
  cloud_free(url, url_psram);
  cJSON_Delete(root);
  cloud_free(resp, from_psram);
  return ret;
}

/****************************************************************************
 * Name: cloud_parse_entry
 *
 * Description:
 *   Map one element of a getResult value array onto struct vs_social_event_s.
 *
 * Returned Value:
 *   true when the entry was understood.  A false is not fatal to the poll:
 *   the caller counts it and moves on, because one malformed entry among
 *   several must not discard the others.
 *
 ****************************************************************************/

static bool cloud_parse_entry(cJSON *entry, struct vs_social_event_s *out)
{
  enum vs_cloud_peer_state_e peer;
  cJSON *response;
  int msg_event = VS_CLOUD_MSG_EVENT_IMAGE;
  int status = 0;

  if (entry == NULL || !cJSON_IsObject(entry) || out == NULL)
    {
      return false;
    }

  memset(out, 0, sizeof(*out));
  out->confidence = 101;

  if (!cloud_json_exact(entry, "msgId", out->msg_id, sizeof(out->msg_id)) ||
      out->msg_id[0] == '\0')
    {
      return false;
    }

  if (!cloud_json_int(entry, "status", &status))
    {
      return false;
    }

  out->raw_status = status;

  switch (status)"}

{"content":"static int cloud_get_result_call(const char *session_id,
                                 const char *const *msg_ids, size_t msg_count,
                                 char *resp, size_t resp_cap, cJSON **root,
                                 cJSON **value)
{
  char *scratch = NULL;
  bool from_psram = false;
  char *request;
  char *query;
  int prefix;
  int status = 0;
  int pos = 0;
  size_t i;
  int http;
  int ret;

  if (session_id == NULL || msg_ids == NULL || msg_count == 0 ||
      msg_count > CLOUD_POLL_MAX_IDS)
    {
      return -EINVAL;
    }

  if (!cloud_id_valid(session_id, VS_CLOUD_SESSION_ID_MAX))
    {
      return -EINVAL;
    }

  /* One allocation for both staging buffers rather than 2.5 KB of frame.
   * This runs on the poll thread and, through vs_cloud_social_get_result(),
   * on the finalize path -- both several calls deep on the 8 KiB stacks the
   * build files declare, with cloud_api_call() and cloud_plain_http() each
   * wanting a kilobyte of their own below this.
   *
   * Two buffers, not three: the encoded form is written straight after the
   * "?data=" prefix inside query rather than into a buffer of its own.  That
   * also keeps the two snprintf() destinations from being provably-disjoint
   * halves of one object, which -Wrestrict cannot see and warns about.
   *
   * cloud_alloc(), not malloc(), for the same reason the response buffers use
   * it: PSRAM first, internal RAM only as a fallback.  This is about 3.5 KB
   * (CLOUD_POLL_MAX_IDS * (VS_CLOUD_MSG_ID_MAX + 4) plus the three-times
   * expansion the URL encoding can need), and plain malloc() of that much was
   * observed failing on every single poll -- "vs_social: poll failed: -12"
   * once per VS_SOCIAL_POLL_INTERVAL_MS for the whole session, measured
   * 2026-08-31, which means no result was ever retrieved even when the
   * uploads themselves succeeded.  CONFIG_RAM_SIZE is 344064 and a session
   * holds four worker stacks (16K + 16K + 8K + 32K) plus live mbedtls
   * contexts in there, so the internal heap is the wrong pool to ask.
   */

  scratch = cloud_alloc(CLOUD_QUERY_REQ_MAX + CLOUD_QUERY_MAX, &from_psram);
  if (scratch == NULL)
    {
      return -ENOMEM;
    }

  request = scratch;
  query = request + CLOUD_QUERY_REQ_MAX;

  pos = snprintf(request, CLOUD_QUERY_REQ_MAX, "{\"msgId\":[");
  for (i = 0; i < msg_count; i++)
    {
      int n;

      if (!cloud_id_valid(msg_ids[i], VS_CLOUD_MSG_ID_MAX))
        {
          printf("%s: refusing to poll unusable msgId\n", CLOUD_TAG);
          ret = -EINVAL;
          goto errout;
        }

      n = snprintf(request + pos, CLOUD_QUERY_REQ_MAX - (size_t)pos,
                   "%s\"%s\"", i == 0 ? "" : ",", msg_ids[i]);
      if (n < 0 || (size_t)(pos + n) >= CLOUD_QUERY_REQ_MAX)
        {
          ret = -E2BIG;
          goto errout;
        }

      pos += n;
    }

  if (snprintf(request + pos, CLOUD_QUERY_REQ_MAX - (size_t)pos,
               "],\"deviceId\":\"%s\",\"sessionId\":\"%s\","
               "\"timestamp\":\"%llu\"}",
               vs_cloud_device_id(), session_id,
               (unsigned long long)cloud_now_ms()) >=
      (int)(CLOUD_QUERY_REQ_MAX - (size_t)pos))
    {
      ret = -E2BIG;
      goto errout;
    }

  prefix = snprintf(query, CLOUD_QUERY_MAX, "%s?data=",
                    CLOUD_PATH_GET_RESULT);
  if (prefix < 0 || (size_t)prefix >= CLOUD_QUERY_MAX)
    {
      ret = -E2BIG;
      goto errout;
    }

  ret = cloud_urlencode(request, query + prefix,
                        CLOUD_QUERY_MAX - (size_t)prefix);
  if (ret < 0)
    {
      goto errout;
    }

  http = cloud_api_call("GET", query, NULL, resp, resp_cap);

  /* Released before the parse below, which is the largest allocation in the
   * call and has no reason to overlap with this one.
   */

  cloud_free(scratch, from_psram);
  scratch = NULL;

  if (http < 0)
    {
      return http;
    }

  if (http < 200 || http >= 300)
    {
      printf("%s: getResult returned HTTP %d\n", CLOUD_TAG, http);
      return -EIO;
    }

  *root = cJSON_Parse(resp);
  ret = cloud_check_envelope(*root, session_id, &status, value);
  if (ret < 0)
    {
      return ret;
    }

  if (status != 0)
    {
      char log[VS_TEXT_SHORT];

      cloud_value_log(*value, *root, log, sizeof(log));
      printf("%s: getResult refused, status %d%s%s\n", CLOUD_TAG, status,
             log[0] != '\0' ? ": " : "", log);
      return -EIO;
    }

  return 0;

errout:
  cloud_free(scratch, from_psram);
  return ret;
}

int vs_cloud_social_poll_event(const char *session_id,
                               const char *const *msg_ids, size_t msg_count,
                               struct vs_social_event_s *out, size_t out_cap,
                               size_t *out_count)
{"}

{"content":"/* ── Persistent connection pool (keep-alive) ─────────────────── */
/* Keeps one live TLS connection per host:port so repeated calls to
 * the same endpoint (Feishu REST, LLM API) skip the TLS handshake. */

#ifdef CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
#define CONN_POOL_SIZE CONFIG_AI_AGENT_TLS_CONN_POOL_SIZE
#else
#define CONN_POOL_SIZE 2
#endif

typedef struct {
    tls_ctx_t ctx;
    char host[128];
    char port[8];
    bool in_use; /* locked by a request */
    bool valid; /* connection is alive */
} conn_slot_t;

static conn_slot_t s_pool[CONN_POOL_SIZE];
static pthread_mutex_t s_pool_lock = PTHREAD_MUTEX_INITIALIZER;

/* Acquire a slot for host:port.  Returns a locked, connected ctx or NULL. */
static conn_slot_t* pool_acquire(const char* host, const char* port)
{
    pthread_mutex_lock(&s_pool_lock);

    /* 1. Find an existing valid slot for this host:port */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        conn_slot_t* s = &s_pool[i];
        if (s->valid && !s->in_use && strcmp(s->host, host) == 0 && strcmp(s->port, port) == 0) {
            s->in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return s;
        }
    }

    /* 2. Find an empty slot */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (!s_pool[i].valid && !s_pool[i].in_use) {
            s_pool[i].in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return &s_pool[i];
        }
    }

    /* 3. Evict the first non-in-use slot */
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (!s_pool[i].in_use) {
            tls_ctx_free(&s_pool[i].ctx);
            s_pool[i].valid = false;
            s_pool[i].in_use = true;
            pthread_mutex_unlock(&s_pool_lock);
            return &s_pool[i];
        }
    }

    pthread_mutex_unlock(&s_pool_lock);
    return NULL; /* all slots busy — caller falls back to ephemeral */
}

/* Return a slot to the pool.  keep=true means the connection is still alive. */
static void pool_release(conn_slot_t* s, const char* host, const char* port, bool keep)
{
    pthread_mutex_lock(&s_pool_lock);
    if (keep) {
        strncpy(s->host, host, sizeof(s->host) - 1);
        strncpy(s->port, port, sizeof(s->port) - 1);
        s->valid = true;
    } else {
        tls_ctx_free(&s->ctx);
        s->valid = false;
        s->host[0] = '\0';
    }
    s->in_use = false;
    pthread_mutex_unlock(&s_pool_lock);
}

void vela_tls_pool_cleanup(void)
{
    pthread_mutex_lock(&s_pool_lock);
    for (int i = 0; i < CONN_POOL_SIZE; i++) {
        if (s_pool[i].in_use) {
            syslog(LOG_WARNING,
                "[vela_tls] Pool slot %d still in use at shutdown, skipping\n", i);
            continue;
        }
        if (s_pool[i].valid) {
            tls_ctx_free(&s_pool[i].ctx);
            s_pool[i].valid = false;
        }
        s_pool[i].host[0] = '\0';
    }
    pthread_mutex_unlock(&s_pool_lock);
}

static int tls_ctx_connect(tls_ctx_t* ctx, const char* host, const char* port)
{
    int ret;

    mbedtls_ssl_init(&ctx->ssl);
    mbedtls_ssl_config_init(&ctx->cfg);
    mbedtls_net_init(&ctx->net);
    mbedtls_ctr_drbg_init(&ctx->ctr_drbg);

    /* Seed RNG directly with our robust function */
    const char* pers = "vela_tls";
    if ((ret = mbedtls_ctr_drbg_seed(&ctx->ctr_drbg, simple_entropy_func, NULL,
             (const unsigned char*)pers,
             strlen(pers)))
        != 0) {
        syslog(LOG_ERR, "[%s] ctr_drbg_seed ret=0x%x\n", TAG, -ret);
        return VELA_TLS_ERR_HANDSHAKE;
    }

    /* Check system time — crucial for TLS certificate validation. */
    time_t now = time(NULL);
    syslog(LOG_DEBUG, "[%s] Handshake start: Host=%s, UNIX=%ld\n", TAG, host, (long)now);

    if (now < 1704067200) { /* Jan 1 2024 */
        syslog(LOG_WARNING, "[%s] Clock too old, forcing to 2026\n", TAG);
        struct timespec ts = { .tv_sec = 1772275200, .tv_nsec = 0 };
        clock_settime(CLOCK_REALTIME, &ts);
    }

    /* TCP connect — use HTTP CONNECT proxy if configured */
#ifdef CONFIG_AI_AGENT_NET_RPMSG
    {
        int res_ret = network_acquire_resource(network_get_connect_timeout() * 1000);
        if (res_ret != 0) {
            syslog(LOG_ERR, "[%s] Resource acquire failed: %d\n", TAG, res_ret);
            return VELA_TLS_ERR_CONNECT;
        }
    }
#endif

    if (http_proxy_is_enabled()) {
        int tunnel_fd = proxy_open_tunnel(host, atoi(port), 30000);
        if (tunnel_fd < 0) {
            syslog(LOG_ERR, "[%s] proxy tunnel to %s:%s failed\n",
                TAG, host, port);
            return VELA_TLS_ERR_CONNECT;
        }
        ctx->net.fd = tunnel_fd;
        syslog(LOG_INFO, "[%s] Using proxy tunnel fd=%d for %s:%s\n",
            TAG, tunnel_fd, host, port);
    } else {
        if ((ret = mbedtls_net_connect(&ctx->net, host, port,
                 MBEDTLS_NET_PROTO_TCP))
            != 0) {
            syslog(LOG_ERR, "[%s] net_connect %s:%s ret=0x%x\n",
                TAG, host, port, -ret);
            return VELA_TLS_ERR_CONNECT;
        }
    }

    /* Force blocking mode and set socket-level read timeout.
     * This avoids using select()/poll() inside mbedtls_net_recv_timeout
     * which returns MBEDTLS_ERR_NET_POLL_FAILED (-0x0047) on NuttX/QEMU.
     * Timeout is configured via AGENT_LLM_SOCKET_TIMEOUT_SEC in
     * agent_config.h.  LLM APIs (especially kimi with thinking mode)
     * can take over 60s for long responses. */
    mbedtls_net_set_block(&ctx->net);
    if (ctx->net.fd >= 0) {
#ifdef CONFIG_AI_AGENT_NET_RPMSG
        int read_timeout_sec = network_get_read_timeout();
        struct timeval tv = { .tv_sec = read_timeout_sec, .tv_usec = 0 };
#else
        struct timeval tv = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
            .tv_usec = 0 };
#endif
        setsockopt(ctx->net.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

#ifdef CONFIG_AI_AGENT_NET_RPMSG
        {
            int timeout_sec = network_get_connect_timeout();
            struct timeval ctv = { .tv_sec = timeout_sec, .tv_usec = 0 };
            setsockopt(ctx->net.fd, SOL_SOCKET, SO_SNDTIMEO, &ctv, sizeof(ctv));
        }
#endif
    }

    /* SSL config: client, TLS, default ciphersuites */
    if ((ret = mbedtls_ssl_config_defaults(&ctx->cfg,
             MBEDTLS_SSL_IS_CLIENT,
             MBEDTLS_SSL_TRANSPORT_STREAM,
             MBEDTLS_SSL_PRESET_DEFAULT))
        != 0) {
        syslog(LOG_ERR, "[%s] ssl_config_defaults ret=0x%x\n", TAG, -ret);
        return VELA_TLS_ERR_HANDSHAKE;
    }

    /* Pin the TLS version range to what is actually compiled in.
     * Setting max to MBEDTLS_SSL_VERSION_TLS1_3 when MBEDTLS_SSL_PROTO_TLS1_3
     * is not defined causes mbedtls_ssl_setup() to return BAD_CONFIG (-0x5e80).
     * Use TLS 1.3 as the ceiling only when the library was built with TLS 1.3
     * support; otherwise cap at TLS 1.2. */
    mbedtls_ssl_conf_min_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
#if defined(MBEDTLS_SSL_PROTO_TLS1_3)
    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_3);
#else
    mbedtls_ssl_conf_max_tls_version(&ctx->cfg, MBEDTLS_SSL_VERSION_TLS1_2);
#endif

    /* Advertise ALPN so Cloudflare/OpenAI servers don't silently reject us.
     * Modern HTTPS servers send a fatal TLS alert or close the connection
     * when no ALPN extension is present in the ClientHello.
     * MBEDTLS_SSL_ALPN must be enabled in the build (it is). */
#if defined(MBEDTLS_SSL_ALPN)
    static const char* alpn_protos[] = { "http/1.1", NULL };
    if ((ret = mbedtls_ssl_conf_alpn_protocols(&ctx->cfg, alpn_protos)) != 0) {
        syslog(LOG_WARNING, "[%s] Failed to set ALPN protocols: -0x%04x (non-fatal)\n", TAG, -ret);
    }
#endif

    /* Skip full chain verification — keeps portability without CA bundle */
    mbedtls_ssl_conf_authmode(&ctx->cfg, MBEDTLS_SSL_VERIFY_OPTIONAL);"}

{"content":"static int tls_write_request(tls_ctx_t* ctx,
    const char* method, const char* host,
    const char* path,
    const vela_header_t* headers,
    const char* body, size_t body_len)
{
    /* Heap-allocate header buffer to reduce stack pressure.
     * This function is called from threads with limited stack
     * (outbound dispatch 16KB) and the TLS context already
     * consumes significant stack space. */
    char* hdr = malloc(4096);
    if (!hdr)
        return VELA_TLS_ERR_OVERFLOW;

    int pos = 0;
    int ret;

#define HDR_APPEND(fmt, ...)                                    \
    pos += snprintf(hdr + pos, 4096 - pos, fmt, ##__VA_ARGS__); \
    if (pos >= 4096) {                                          \
        free(hdr);                                              \
        return VELA_TLS_ERR_OVERFLOW;                           \
    }

    HDR_APPEND("%s %s HTTP/1.1\r\n", method, path);
    HDR_APPEND("Host: %s\r\n", host);
    HDR_APPEND("Connection: keep-alive\r\n");
    HDR_APPEND("User-Agent: agent-vela/1.0\r\n");

    if (body && body_len > 0) {
        HDR_APPEND("Content-Length: %zu\r\n", body_len);
    }

    if (headers) {
        for (const vela_header_t* h = headers; h->name != NULL; h++) {
            HDR_APPEND("%s: %s\r\n", h->name, h->value);
        }
    }

    HDR_APPEND("\r\n");
#undef HDR_APPEND

    /* Write headers */
    int written = 0;
    while (written < pos) {
        ret = mbedtls_ssl_write(&ctx->ssl,
            (const unsigned char*)(hdr + written),
            (size_t)(pos - written));
        if (ret > 0) {
            written += ret;
        } else if (ret == 0) {
            free(hdr);
            return VELA_TLS_ERR_WRITE;
        } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
            free(hdr);
            return VELA_TLS_ERR_WRITE;
        }
    }

    free(hdr);

    /* Write body */
    if (body && body_len > 0) {
        size_t bw = 0;
        while (bw < body_len) {
            ret = mbedtls_ssl_write(&ctx->ssl,
                (const unsigned char*)(body + bw),
                body_len - bw);
            if (ret > 0) {
                bw += (size_t)ret;
            } else if (ret == 0) {
                return VELA_TLS_ERR_WRITE;
            } else if (ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
                return VELA_TLS_ERR_WRITE;
            }
        }
    }

    return 0;
}

/**
 * Read full HTTP/1.1 response.
 * Returns HTTP status code; writes body into resp_buf (NUL-terminated).
 * Handles Transfer-Encoding: chunked and Content-Length.
 */
#define TLS_RAW_BUF_SIZE 8192  /* 8KB: enough for HTTP headers + initial body */

/* Number of static raw buffers — at most 2, scaled to pool size.
 * Each buffer is 8KB; pool=1 uses 1 buffer, pool>=2 uses 2. */
#define TLS_RAW_BUF_COUNT (CONN_POOL_SIZE < 2 ? 1 : 2)

static char s_tls_raw_buf[TLS_RAW_BUF_COUNT][TLS_RAW_BUF_SIZE];
static pthread_mutex_t s_tls_raw_lock[TLS_RAW_BUF_COUNT];
static pthread_once_t s_tls_raw_once = PTHREAD_ONCE_INIT;

static void tls_raw_init_once(void)
{
    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
        pthread_mutex_init(&s_tls_raw_lock[i], NULL);
    }
}

static char* tls_raw_acquire(void)
{
    pthread_once(&s_tls_raw_once, tls_raw_init_once);
    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
        if (pthread_mutex_trylock(&s_tls_raw_lock[i]) == 0) {
            return s_tls_raw_buf[i];
        }
    }
    /* All busy — block on first */
    pthread_mutex_lock(&s_tls_raw_lock[0]);
    return s_tls_raw_buf[0];
}

static void tls_raw_release(char* buf)
{
    for (int i = 0; i < TLS_RAW_BUF_COUNT; i++) {
        if (buf == s_tls_raw_buf[i]) {
            pthread_mutex_unlock(&s_tls_raw_lock[i]);
            return;
        }
    }
}

/**
 * Read one response.
 *
 * Two modes, chosen by sink.  With sink NULL the body is collected into
 * resp_buf and truncated at resp_cap, which is what every caller before the
 * streaming API wanted.  With sink set, resp_buf is unused and the body is
 * handed on as it arrives, so the body may be any size; see
 * vela_https_request_stream().
 */

static int tls_read_response(tls_ctx_t* ctx, char* resp_buf, size_t resp_cap,
    size_t* out_body_len, bool* out_keep_alive,
    vela_body_sink_t sink, void* sink_arg)
{
    /* Use static buffers to avoid heap fragmentation */
    char* raw = tls_raw_acquire();
    size_t raw_len = 0;
    int eof = 0;
    int ret;

    /* Read until we have the full header (double CRLF) or buffer full */
    while (!eof && raw_len < TLS_RAW_BUF_SIZE - 1) {
        ret = mbedtls_ssl_read(&ctx->ssl,
            (unsigned char*)(raw + raw_len),
            TLS_RAW_BUF_SIZE - 1 - raw_len);
        if (ret > 0) {
            raw_len += (size_t)ret;
            if (memmem(raw, raw_len, "\r\n\r\n", 4))
                break;
        } else if (ret == 0 || ret == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
            eof = 1;
            break;
        } else if (ret != MBEDTLS_ERR_SSL_WANT_READ) {
            syslog(LOG_ERR, "[%s] ssl_read (header) ret=0x%x\n", TAG, -ret);
            tls_raw_release(raw);
            return VELA_TLS_ERR_READ;
        }
    }
    raw[raw_len] = '\0';

    /* Parse status line */
    int http_status = 0;
    if (sscanf(raw, "HTTP/1.%*d %d", &http_status) != 1) {
        syslog(LOG_ERR, "[%s] Failed to parse HTTP status from: %.80s\n", TAG, raw);
        tls_raw_release(raw);
        return VELA_TLS_ERR_READ;
    }

    /* Find header/body split */
    char* body_start = (char*)memmem(raw, raw_len, "\r\n\r\n", 4);
    if (!body_start) {
        if (resp_buf && resp_cap)
            resp_buf[0] = '\0';
        tls_raw_release(raw);
        return http_status;
    }"}

{"content":"    const char* port,
    const char* method,
    const char* path,
    const vela_header_t* headers,
    const char* body,
    size_t body_len,
    char* resp_buf,
    size_t resp_cap,
    size_t* out_body_len,
    vela_body_sink_t sink,
    void* sink_arg)
{
    int ret;

    /* Try to get a pooled connection first */
    conn_slot_t* slot = pool_acquire(host, port);

    if (slot && slot->valid) {
        /* Drain any leftover data from previous response before reuse.
         * Without this, a partially-read response body (e.g. truncated
         * chunked data) would be misinterpreted as the next HTTP status. */
        if (slot->ctx.net.fd >= 0) {
            unsigned char drain[512];
            int dr;
            /* Temporarily set a very short socket timeout to drain without blocking */
            struct timeval tv_drain = { .tv_sec = 0, .tv_usec = 10000 }; /* 10ms */
            struct timeval tv_orig = { .tv_sec = AGENT_LLM_SOCKET_TIMEOUT_SEC,
                .tv_usec = 0 };
            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
                &tv_drain, sizeof(tv_drain));
            while ((dr = mbedtls_ssl_read(&slot->ctx.ssl, drain, sizeof(drain))) > 0)
                ; /* discard leftover bytes */
            /* Restore original timeout */
            setsockopt(slot->ctx.net.fd, SOL_SOCKET, SO_RCVTIMEO,
                &tv_orig, sizeof(tv_orig));
            /* If peer closed the connection, reconnect */
            if (dr == 0 || dr == MBEDTLS_ERR_SSL_PEER_CLOSE_NOTIFY) {
                goto pool_reconnect;
            }
        } else {
            goto pool_reconnect;
        }

        /* Reuse existing connection — skip TLS handshake */
        syslog(LOG_DEBUG, "[%s] Reusing pooled connection to %s:%s\n", TAG, host, port);
        ret = tls_write_request(&slot->ctx, method, host, path, headers, body, body_len);
        if (ret == 0) {
            size_t got = 0;
            bool keep = false;

            /* Counted locally rather than only through out_body_len, which the
             * caller may not have asked for.  How much reached the sink is what
             * decides whether this may be retried, so it cannot be optional.
             */

            ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, &got,
                &keep, sink, sink_arg);
            if (out_body_len)
                *out_body_len = got;

            if (ret > 0) {
                pool_release(slot, host, port, keep);
                return ret;
            }

            /* Do not retry a streaming request that already handed bytes over.
             * The retry below exists for a connection the server closed while
             * it sat idle, which is discovered on write and produces nothing;
             * once the sink has been fed, reissuing the request would append a
             * second copy of the body to whatever the first attempt wrote.
             *
             * A sink that refused and framing this side could not follow are
             * answers in their own right, not stale connections, so they end
             * here too even when nothing was delivered.
             */

            if (sink != NULL && (got > 0 || ret == VELA_TLS_ERR_SINK ||
                    ret == VELA_TLS_ERR_PROTOCOL)) {
                pool_release(slot, host, port, false);
                return ret;
            }
        }
        /* Connection went stale — fall through to reconnect */
    pool_reconnect:
        syslog(LOG_INFO, "[%s] Pooled connection stale, reconnecting\n", TAG);
        tls_ctx_free(&slot->ctx);
        slot->valid = false;
    }

    /* New connection */
    if (!slot) {
        /* Pool full — use a temporary ephemeral context */
        tls_ctx_t tmp_ctx;
        if ((ret = tls_ctx_connect(&tmp_ctx, host, port)) != 0) {
            tls_ctx_free(&tmp_ctx);
            return ret;
        }
        if ((ret = tls_write_request(&tmp_ctx, method, host, path,
                 headers, body, body_len))
            != 0) {
            syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
            tls_ctx_free(&tmp_ctx);
            return ret;
        }
        ret = tls_read_response(&tmp_ctx, resp_buf, resp_cap, out_body_len, NULL,
            sink, sink_arg);
        tls_ctx_free(&tmp_ctx);
        return ret;
    }

    /* Connect into the slot */
    if ((ret = tls_ctx_connect(&slot->ctx, host, port)) != 0) {
        pool_release(slot, host, port, false);
        return ret;
    }

    if ((ret = tls_write_request(&slot->ctx, method, host, path,
             headers, body, body_len))
        != 0) {
        syslog(LOG_ERR, "[%s] Write request failed: %d\n", TAG, ret);
        pool_release(slot, host, port, false);
        return ret;
    }

    bool keep = false;
    ret = tls_read_response(&slot->ctx, resp_buf, resp_cap, out_body_len, &keep,
        sink, sink_arg);
    pool_release(slot, host, port, ret > 0 && keep);
    return ret;
}

int vela_https_request(
    const char* host,
    const char* port,
    const char* method,
    const char* path,
    const vela_header_t* headers,
    const char* body,
    size_t body_len,
    char* resp_buf,
    size_t resp_cap,
    size_t* out_body_len)
{
    return tls_do_request(host, port, method, path, headers, body, body_len,
        resp_buf, resp_cap, out_body_len, NULL, NULL);
}

int vela_https_request_stream(
    const char* host,
    const char* port,
    const char* method,
    const char* path,
    const vela_header_t* headers,
    const char* body,
    size_t body_len,
    vela_body_sink_t sink,
    void* sink_arg,
    size_t* out_body_len)
{
    if (sink == NULL) {
        return VELA_TLS_ERR_SINK;
    }

    /* No response buffer at all: the streaming path in tls_read_response()
     * never writes one, and passing NULL here makes that a compile-time
     * certainty rather than a convention.
     */

    return tls_do_request(host, port, method, path, headers, body, body_len,
        NULL, 0, out_body_len, sink, sink_arg);
}

int vela_https_get(const char* host, const char* port, const char* path,
    char* resp_buf, size_t resp_cap)
{
    return vela_https_request(host, port, "GET", path, NULL, NULL, 0,
        resp_buf, resp_cap, NULL);
}

