  if (event->type == VS_INPUT_PROGRESS && event->key == VS_KEY_NEXT &&
      runtime->page == VS_PAGE_SOFTAP && !runtime->network_busy)
    {
      runtime->ap_reset_holding = true;
      runtime->progress = event->progress;
      return;
