int vs_display_open(struct vs_display_s **display)
{
  struct vs_display_s *state;
  lv_nuttx_dsc_t descriptor;
  int ret;

  if (display == NULL)
    return -EINVAL;

  state = calloc(1, sizeof(*state));
  if (state == NULL)
    return -ENOMEM;

  lv_init();
  lv_nuttx_dsc_init(&descriptor);
  descriptor.fb_path = "/dev/fb0";
  lv_nuttx_init(&descriptor, &state->nuttx);
  if (state->nuttx.disp == NULL)
    {
      free(state);
      return -ENODEV;
    }

  ret = vs_panel_init(&state->panel[VS_STATUS_PANEL], state->nuttx.disp);
  if (ret < 0)
    goto fail_status;

  state->panel[VS_CONTENT_PANEL].display = lv_nuttx_fbdev_create();
  if (state->panel[VS_CONTENT_PANEL].display == NULL ||
      lv_nuttx_fbdev_set_file(state->panel[VS_CONTENT_PANEL].display,
                              "/dev/fb1") < 0)
    {
      ret = -ENODEV;
      goto fail_content;
    }

  ret = vs_panel_init(&state->panel[VS_CONTENT_PANEL],
                      state->panel[VS_CONTENT_PANEL].display);
  if (ret < 0)
    goto fail_content;

  *display = state;
  return 0;

fail_content:
  if (state->panel[VS_CONTENT_PANEL].display != NULL)
    lv_display_delete(state->panel[VS_CONTENT_PANEL].display);
fail_status:
  lv_nuttx_deinit(&state->nuttx);"}

{"content":"int vs_display_render(struct vs_display_s *display,
                      const struct vs_ui_snapshot_s *snapshot)
{
  bool content_dirty;
  bool status_dirty;

  if (display == NULL || snapshot == NULL)
    return -EINVAL;

  /* fb1 is the physical left content display; fb0 is the physical right
   * status display. */
  content_dirty = !display->previous_valid ||
                  vs_content_changed(snapshot, &display->previous);
  status_dirty = !display->previous_valid ||
                 vs_status_changed(snapshot, &display->previous);
  if (content_dirty)
    vs_render_content(&display->panel[VS_CONTENT_PANEL], snapshot);
  if (status_dirty)
    vs_render_status(&display->panel[VS_STATUS_PANEL], snapshot);

  if (!display->revealed)
    {
      /* Match the old synchronous boot animation's hand-off: both complete
       * frames must reach panel GRAM before the shared backlight is enabled.
       * lv_refr_now() executes each framebuffer's FBIO_UPDATE synchronously. */

      lv_obj_invalidate(display->panel[VS_STATUS_PANEL].screen);
      lv_obj_invalidate(display->panel[VS_CONTENT_PANEL].screen);
      lv_refr_now(display->panel[VS_STATUS_PANEL].display);
      lv_refr_now(display->panel[VS_CONTENT_PANEL].display);
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_264_VELASIGHT
      bk7258_display_reveal();
#endif
      display->revealed = true;
    }
  /* After reveal, LVGL's 100 ms display timers coalesce invalidations and cap
   * each panel at 10 FPS.  Only the hidden boot hand-off bypasses that cap. */
  display->previous = *snapshot;
  display->previous_valid = true;
  display->waiting = snapshot->progress_kind == VS_PROGRESS_WAIT;
  snprintf(display->wait_meta, sizeof(display->wait_meta), "%s",
           snapshot->status_meta);
  if (!display->waiting)
    {
      display->wait_phase = 0;
      display->wait_next_ms = 0;
    }
  return 0;
}

void vs_display_tick(struct vs_display_s *display)
{
  if (display != NULL)
    {
      uint32_t now = vs_display_now_ms();

      if (display->waiting &&
          (display->wait_next_ms == 0 ||
           (int32_t)(now - display->wait_next_ms) >= 0))
        {
          static const char *const phases[] = {".", "..", "...", ""};
          char meta[VS_TEXT_LONG];

          snprintf(meta, sizeof(meta), "%s%s", display->wait_meta,
                   phases[display->wait_phase]);
          vs_set_label(display->panel[VS_CONTENT_PANEL].status_line[1],
                       meta);
          display->wait_phase = (display->wait_phase + 1) % 4;
          display->wait_next_ms = now + 350;
        }
      lv_timer_handler();
    }
}

void vs_display_flush(struct vs_display_s *display)
{
  if (display == NULL)
    {
      return;
    }

  /* Both panels, and both synchronously: the two screens carry halves of one
   * message, and lv_refr_now() runs each framebuffer's FBIO_UPDATE before it
   * returns.  This is the same hand-off the boot reveal uses.
   */

  lv_refr_now(display->panel[VS_STATUS_PANEL].display);
  lv_refr_now(display->panel[VS_CONTENT_PANEL].display);
}

void vs_display_close(struct vs_display_s *display)
{
  if (display == NULL)
    return;

  if (display->panel[VS_CONTENT_PANEL].display != NULL)
    lv_display_delete(display->panel[VS_CONTENT_PANEL].display);
  lv_nuttx_deinit(&display->nuttx);
  lv_deinit();"}

{"content":"/****************************************************************************
 * Name: cloud_classify_emotion
 *
 * Description:
 *   Turn the cloud's (emotionColor, emotionDetail) pair into the UI's
 *   vocabulary.
 *
 *   The colour is the authoritative part -- the document fixes the three
 *   buckets and enumerates which details fall in each -- so the detail is
 *   consulted only to split green, whose two members (愉悦, 中立) are the one
 *   place where a single colour spans two of the UI's emotions.
 *
 *   The RGB values are the palette vs_app.c already uses for its own
 *   defaults, so a cloud-driven colour and a locally-derived one look the
 *   same.  Blue has no local equivalent (vs_app.c maps CONFUSED to amber) and
 *   gets a real blue here, because the cloud's three-colour scheme is
 *   something the user is meant to be able to read off the screen.
 *
 * Input Parameters:
 *   extreme - set true only for the red bucket.  This is the device's only
 *             way to tell an extreme frame from a calm one: the peer-side
 *             status collapses the cloud's 20 and 21 into a single 20.
 *
 ****************************************************************************/

static void cloud_classify_emotion(const char *color, const char *detail,
                                   enum vs_emotion_e *emotion, uint32_t *rgb,
                                   bool *extreme)
{
  *emotion = VS_EMOTION_NONE;
  *rgb = 0xe8eef2;
  *extreme = false;

  if (color == NULL)
    {
      return;
    }

  if (strcasecmp(color, "red") == 0)
    {
      *emotion = VS_EMOTION_TENSE;
      *rgb = 0xe85d5d;
      *extreme = true;
    }
  else if (strcasecmp(color, "blue") == 0)
    {
      *emotion = VS_EMOTION_CONFUSED;
      *rgb = 0x5d8fe8;
    }
  else if (strcasecmp(color, "green") == 0)
    {
      if (detail != NULL && strstr(detail, "愉悦") != NULL)
        {
          *emotion = VS_EMOTION_HAPPY;
          *rgb = 0x48c78e;
        }
      else
        {
          *emotion = VS_EMOTION_CALM;
          *rgb = 0xe8eef2;
        }
    }
}

/****************************************************************************
 * Name: cloud_check_envelope
 *
 * Description:
 *   Validate the parts every /contest/v1 response shares and hand back the
 *   "value" member.
 *
 *   The sessionId echo is checked rather than trusted.  One deviceId may only
 *   have one live session, and the cloud replaces an old session with a newer
 *   one, so a reply carrying a different sessionId means this session has
 *   already been superseded -- continuing to feed it frames would attribute
 *   them to a session that no longer exists.
 *
 * Returned Value:
 *   0 with *status and *value filled, or a negative errno.
 *
 ****************************************************************************/

static int cloud_check_envelope(cJSON *root, const char *session_id,
                                int *status, cJSON **value)
{
  char echoed[VS_CLOUD_SESSION_ID_MAX];

  if (root == NULL || !cJSON_IsObject(root))
    {
      return -EPROTO;
    }

  if (!cloud_json_int(root, "status", status))
    {
      printf("%s: response has no status\n", CLOUD_TAG);
      return -EPROTO;
    }

  if (session_id != NULL &&
      cloud_json_exact(root, "sessionId", echoed, sizeof(echoed)) &&
      echoed[0] != '\0' && strcmp(echoed, session_id) != 0)
    {
      printf("%s: session mismatch, sent %s got %s\n", CLOUD_TAG,
             session_id, echoed);
      return -ESTALE;
    }

  *value = cJSON_GetObjectItem(root, "value");
  return 0;
}

