                              size_t max_bytes, size_t *len)
{
  struct cloud_url_s *parsed = NULL;
  struct cloud_file_sink_s sink;
  char *scratch = NULL;
  bool parsed_psram = false;
  bool scratch_psram = false;

  /* Zeroed by the fallback path when the store will not take a Range header,
   * which is what makes "windowed" a runtime property rather than a build one.
   */

  size_t window = CONFIG_VS_SOCIAL_DOWNLOAD_WINDOW_BYTES;
  unsigned int stalls = 0;
  unsigned int requests = 0;
  bool complete = false;
  int http;
  int ret;

  if (url == NULL || url[0] == '\0' || path == NULL || max_bytes == 0)
    {
      return -EINVAL;
    }

  if (len != NULL)
    {
      *len = 0;
    }

  memset(&sink, 0, sizeof(sink));
  sink.fd = -1;
  sink.max_bytes = max_bytes;
  sink.next_report = CLOUD_DOWNLOAD_REPORT_STRIDE;

  /* The write aggregation buffer.  Optional by design: cloud_file_sink() falls
   * back to writing each record straight through when this is NULL, which is
   * slow but still correct.  See CONFIG_VS_SOCIAL_DOWNLOAD_BLOCK_BYTES.
   */

  sink.buf = cloud_alloc(CONFIG_VS_SOCIAL_DOWNLOAD_BLOCK_BYTES,
                         &sink.buf_psram);
  if (sink.buf != NULL)
    {
      sink.cap = CONFIG_VS_SOCIAL_DOWNLOAD_BLOCK_BYTES;
    }
  else
    {
      printf("%s: no %d byte download buffer, writing unaggregated\n",
             CLOUD_TAG, CONFIG_VS_SOCIAL_DOWNLOAD_BLOCK_BYTES);
    }

  parsed = cloud_alloc(sizeof(*parsed), &parsed_psram);
  if (parsed == NULL)
    {
      cloud_free(sink.buf, sink.buf_psram);
      return -ENOMEM;
    }

  ret = cloud_url_parse(url, parsed);
  if (ret < 0)
    {
      if (ret == -EPROTONOSUPPORT)
        {
          printf("%s: cannot download %s, unsupported scheme\n", CLOUD_TAG,
                 url);
        }

      goto out;
    }

