input.newStr:
 * Input Parameters:
 *   extreme - set from the detail, because that is where the cloud's rule
 *             lives.  It has to be derived at all because the peer-side status
 *             collapses the cloud's 20 and 21 into a single 20, so status
 *             cannot tell an extreme frame from a calm one.
 *
 *             The rule is two named emotions: 生气 or 伤心, one occurrence.
 *             Not the red bucket, which is what this used to test and which is
 *             wrong in both directions -- red also contains 反感, which does
 *             not trigger, and 伤心 is blue.  So colour and extreme are
 *             independent axes now and a frame can be blue and extreme at the
 *             same time.  A caller that wants the cloud's own answer instead of
 *             this inference should overwrite it; see cloud_json_extreme().
 *
 ****************************************************************************/

static void cloud_classify_emotion(const char *color, const char *detail,
                                   enum vs_emotion_e *emotion, uint32_t *rgb,
                                   bool *extreme)
{
  *emotion = VS_EMOTION_NONE;
  *rgb = 0xe8eef2;

  /* Independent of the colour branches below, and deliberately evaluated
   * before them so it is obvious that no branch sets it.
   */

  *extreme = detail != NULL &&
             (strstr(detail, "生气") != NULL ||
              strstr(detail, "伤心") != NULL);

  if (color == NULL)
    {
      return;
    }

  if (strcasecmp(color, "red") == 0)
    {
      *emotion = VS_EMOTION_TENSE;
      *rgb = 0xe85d5d;
    }
  else if (strcasecmp(color, "blue") == 0)
    {
      *emotion = VS_EMOTION_CONFUSED;
      *rgb = 0x5d8fe8;
    }

/****************************************************************************
 * Name: cloud_json_extreme
 *
 * Description:
 *   The cloud's own extreme verdict, when it sends one.
 *
 *   The rule that decides it -- one 生气 or one 伤心 -- is evaluated on the
 *   cloud, and cloud_classify_emotion() reproduces it from emotionDetail so the
 *   device works whether or not the answer is transmitted.  Reproducing a
 *   decision is not the same as being told it, though: a rule that changes on
 *   the cloud silently stops matching here, and the detail strings are the only
 *   thing the inference has to go on.  So if the flag is present it wins.
 *
 *   Three spellings are accepted.  The rule was described to this project as
 *   "is_extreme", the interface document's other fields are lowerCamelCase, and
 *   a bare "extreme" is the obvious third guess; accepting all three costs two
 *   string compares on a path that already parses four fields, and guessing
 *   wrong costs the feature.
 *
 *   Numbers and strings are accepted as well as JSON booleans, for the same
 *   reason cloud_json_confidence() accepts a number where the document shows a
 *   string: every field in this interface is documented as String and the
 *   staging cloud does not always agree.
 *
 * Input Parameters:
 *   fallback - what to report when no flag is present, which is the value
 *              cloud_classify_emotion() inferred.
 *
 ****************************************************************************/

static bool cloud_json_extreme(const cJSON *obj, bool fallback)
{
  static const char *const names[] =
  {
    "isExtreme", "is_extreme", "extreme"
  };

  size_t i;

  if (obj == NULL)
    {
      return fallback;
    }

  for (i = 0; i < sizeof(names) / sizeof(names[0]); i++)
    {
      cJSON *item = cJSON_GetObjectItem((cJSON *)obj, names[i]);

      if (item == NULL || cJSON_IsNull(item))
        {
          continue;
        }

      if (cJSON_IsBool(item))
        {
          return cJSON_IsTrue(item) ? true : false;
        }

      if (cJSON_IsNumber(item))
        {
          return item->valuedouble != 0.0;
        }

      if (cJSON_IsString(item) && item->valuestring != NULL)
        {
          return strcasecmp(item->valuestring, "true") == 0 ||
                 strcasecmp(item->valuestring, "1") == 0;
        }
    }

  return fallback;
}

