  lv_obj_set_size(label, width, height);
  lv_obj_set_style_text_color(label, color, 0);
  lv_obj_set_style_text_align(label, LV_TEXT_ALIGN_CENTER, 0);
  lv_obj_set_style_text_font(label, &velasight_font_16_ui, 0);
  lv_label_set_long_mode(label, LV_LABEL_LONG_WRAP);
}

static void vs_divider_style(lv_obj_t *divider, int32_t x, int32_t y,
                             int32_t width)
{
  lv_obj_set_pos(divider, x, y);
  lv_obj_set_size(divider, width, 1);
  lv_obj_set_style_bg_color(divider, vs_rgb(27, 55, 72), 0);
  lv_obj_set_style_bg_opa(divider, LV_OPA_COVER, 0);
  lv_obj_set_style_border_width(divider, 0, 0);
  lv_obj_set_style_radius(divider, 0, 0);
}

static int vs_panel_init(struct vs_panel_s *panel, lv_display_t *display)
{
  lv_obj_t *screen;
  int key;

  if (panel == NULL || display == NULL)
    return -EINVAL;

  memset(panel, 0, sizeof(*panel));
  panel->display = display;
  screen = lv_display_get_screen_active(display);
  panel->screen = screen;
  lv_obj_set_style_bg_color(screen, vs_rgb(7, 12, 21), 0);
  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);

  panel->title = lv_label_create(screen);
  panel->body = lv_label_create(screen);
  panel->meta = lv_label_create(screen);
  panel->status_line[0] = lv_label_create(screen);
  panel->status_line[1] = lv_label_create(screen);
  panel->divider[0] = lv_obj_create(screen);
  panel->divider[1] = lv_obj_create(screen);
  if (panel->title == NULL || panel->body == NULL || panel->meta == NULL ||
      panel->status_line[0] == NULL || panel->status_line[1] == NULL ||
      panel->divider[0] == NULL || panel->divider[1] == NULL)
    return -ENOMEM;

  vs_label_style(panel->title, vs_rgb(128, 170, 185), VS_TITLE_X,
                 VS_TITLE_Y, VS_TITLE_WIDTH, VS_TITLE_HEIGHT);
  vs_label_style(panel->body, vs_rgb(235, 242, 246), VS_MAIN_X, VS_MAIN_Y,
                 VS_MAIN_WIDTH, VS_MAIN_HEIGHT);
  vs_label_style(panel->meta, vs_rgb(52, 201, 173), VS_META_X,
                 VS_LOWER_BOTTOM_Y, VS_META_WIDTH, VS_LOWER_ROW_HEIGHT);
  lv_label_set_long_mode(panel->title, LV_LABEL_LONG_CLIP);
  lv_label_set_long_mode(panel->meta, LV_LABEL_LONG_CLIP);
  for (int line = 0; line < 2; line++)
    {
      vs_label_style(panel->status_line[line], vs_rgb(155, 175, 187),
                     28, 110 + line * 20, 104, VS_LOWER_ROW_HEIGHT);
      lv_label_set_long_mode(panel->status_line[line], LV_LABEL_LONG_CLIP);
      lv_obj_add_flag(panel->status_line[line], LV_OBJ_FLAG_HIDDEN);
    }
  lv_obj_set_pos(panel->status_line[1], 28, VS_LOWER_BOTTOM_Y);
  lv_obj_set_width(panel->status_line[1], 104);
  lv_obj_set_style_text_color(panel->status_line[1], vs_rgb(52, 201, 173), 0);
  vs_divider_style(panel->divider[0], 20, VS_TOP_DIVIDER_Y, 120);
  vs_divider_style(panel->divider[1], 12, VS_BOTTOM_DIVIDER_Y, 136);

  for (key = 0; key < VS_KEY_COUNT; key++)
    {
      panel->key[key] = lv_label_create(screen);
      if (panel->key[key] == NULL)
        return -ENOMEM;

      vs_label_style(panel->key[key], vs_rgb(155, 175, 187),
                     key == VS_KEY_NEXT ? 80 : 16, VS_LOWER_TOP_Y, 64,
                     VS_LOWER_ROW_HEIGHT);
      lv_label_set_long_mode(panel->key[key], LV_LABEL_LONG_CLIP);
      lv_obj_set_style_bg_opa(panel->key[key], LV_OPA_TRANSP, 0);
    }

  panel->progress = lv_arc_create(screen);
  if (panel->progress == NULL)
    return -ENOMEM;

  lv_obj_set_size(panel->progress, VS_RING_SIZE, VS_RING_SIZE);
  lv_obj_center(panel->progress);
  lv_arc_set_range(panel->progress, 0, 100);
  lv_arc_set_bg_angles(panel->progress, VS_HOLD_ANGLE_START,
                       VS_HOLD_ANGLE_END);
  lv_arc_set_value(panel->progress, 0);
  panel->ring_start = VS_HOLD_ANGLE_START;
  panel->ring_end = VS_HOLD_ANGLE_END;
  lv_obj_set_style_arc_color(panel->progress, vs_rgb(27, 55, 72), LV_PART_MAIN);
  lv_obj_set_style_arc_width(panel->progress, 4, LV_PART_MAIN);
  lv_obj_set_style_arc_color(panel->progress, vs_rgb(53, 199, 174), LV_PART_INDICATOR);
  lv_obj_set_style_arc_width(panel->progress, 4, LV_PART_INDICATOR);
  lv_obj_set_style_opa(panel->progress, LV_OPA_TRANSP, LV_PART_KNOB);
  lv_obj_add_flag(panel->progress, LV_OBJ_FLAG_HIDDEN);
  lv_timer_set_period(lv_display_get_refr_timer(display),
                      VS_FRAME_INTERVAL_MS);
  return 0;
}

static void vs_set_label(lv_obj_t *label, const char *text)
{
  const char *value = text != NULL ? text : "";

  if (strcmp(lv_label_get_text(label), value) != 0)
    lv_label_set_text(label, value);
}

static void vs_set_hidden(lv_obj_t *obj, bool hidden)
{
  if (lv_obj_has_flag(obj, LV_OBJ_FLAG_HIDDEN) == hidden)
    return;

  if (hidden)
    lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);
  else
    lv_obj_remove_flag(obj, LV_OBJ_FLAG_HIDDEN);
}

static void vs_set_text_color(lv_obj_t *obj, lv_color_t color)
{
  if (!lv_color_eq(lv_obj_get_style_text_color(obj, 0), color))
    lv_obj_set_style_text_color(obj, color, 0);
}

static void vs_set_bg_color(lv_obj_t *obj, lv_color_t color)
{
  if (!lv_color_eq(lv_obj_get_style_bg_color(obj, 0), color))
    lv_obj_set_style_bg_color(obj, color, 0);
}

static void vs_set_bg_opa(lv_obj_t *obj, lv_opa_t opa)
{
  if (lv_obj_get_style_bg_opa(obj, 0) != opa)
    lv_obj_set_style_bg_opa(obj, opa, 0);
}

static bool vs_key_changed(const struct vs_softkey_s *current,
                           const struct vs_softkey_s *previous)
{
  return current->visible != previous->visible ||
         current->highlighted != previous->highlighted ||
         strcmp(current->text, previous->text) != 0;
}

static bool vs_content_changed(const struct vs_ui_snapshot_s *current,
                               const struct vs_ui_snapshot_s *previous)
{
  return current->page != previous->page ||
         current->history_is_blank != previous->history_is_blank ||
         current->wifi_ready != previous->wifi_ready ||
         current->network.wifi_issue != previous->network.wifi_issue ||
         current->network.ap_client_count !=
         previous->network.ap_client_count ||
         strcmp(current->content_title, previous->content_title) != 0 ||
         strcmp(current->content_body, previous->content_body) != 0 ||
         strcmp(current->content_meta, previous->content_meta) != 0 ||
         strcmp(current->status_meta, previous->status_meta) != 0;
}

static bool vs_status_changed(const struct vs_ui_snapshot_s *current,
                              const struct vs_ui_snapshot_s *previous)
{
  return current->page != previous->page ||
         current->progress != previous->progress ||
         current->progress_kind != previous->progress_kind ||
         current->emotion_color != previous->emotion_color ||
         strcmp(current->status_title, previous->status_title) != 0 ||
         strcmp(current->status_value, previous->status_value) != 0 ||
         vs_key_changed(&current->softkey[VS_KEY_BACK],
                        &previous->softkey[VS_KEY_BACK]) ||
         vs_key_changed(&current->softkey[VS_KEY_CONFIRM],
                        &previous->softkey[VS_KEY_CONFIRM]) ||
         vs_key_changed(&current->softkey[VS_KEY_NEXT],
                        &previous->softkey[VS_KEY_NEXT]);
}

static void vs_panel_set_progress(struct vs_panel_s *panel,
                                  const struct vs_ui_snapshot_s *snapshot,
                                  bool visible)
{
  if (visible)
    {
      int32_t start = snapshot->progress_kind == VS_PROGRESS_LEVEL ?
                      VS_LEVEL_ANGLE_START : VS_HOLD_ANGLE_START;
      int32_t end = snapshot->progress_kind == VS_PROGRESS_LEVEL ?
                    VS_LEVEL_ANGLE_END : VS_HOLD_ANGLE_END;

      /* Only the background sweep is programmed here.  The value is the single
       * source of truth for how far the ring is filled, and
       * lv_arc_set_bg_angles() ends in lv_arc's value_update(), so changing the
       * sweep re-derives the indicator from the value on its own.
       *
       * lv_arc_set_angles() must not be used alongside it.  That call writes
       * the indicator angles directly -- passing the full sweep pegs the ring
       * at 100% -- and lv_arc_set_value() cannot put it back, because it
       * returns early when the value has not changed (lv_arc.c:237).  A level
       * being redrawn has an unchanged value by definition, which is why the
       * volume ring read full on every repaint after the first.
       */

      if (panel->ring_start != start || panel->ring_end != end)
        {
          lv_arc_set_bg_angles(panel->progress, start, end);
          panel->ring_start = start;
          panel->ring_end = end;
        }

      vs_set_hidden(panel->progress, false);
      lv_arc_set_value(panel->progress, snapshot->progress);
    }
  else
    vs_set_hidden(panel->progress, true);
}

static void vs_panel_set_keys(struct vs_panel_s *panel,
                              const struct vs_ui_snapshot_s *snapshot,
                              bool content_panel)
{
  int key;

  for (key = 0; key < VS_KEY_COUNT; key++)
    {
      bool visible = snapshot->softkey[key].visible;

      /* The left footer carries metadata and short status only.  The right
       * footer is fixed: back/next on the first row, confirm on the second. */
      if (content_panel)
        visible = false;
      else
        {
          if (key == VS_KEY_BACK)
            {
              lv_obj_set_pos(panel->key[key], 8, VS_LOWER_TOP_Y);
              lv_obj_set_width(panel->key[key], 64);
            }
          else if (key == VS_KEY_NEXT)
            {
              lv_obj_set_pos(panel->key[key], 88, VS_LOWER_TOP_Y);
              lv_obj_set_width(panel->key[key], 64);
            }
          else
            {
              lv_obj_set_pos(panel->key[key], 28, VS_LOWER_BOTTOM_Y);
              lv_obj_set_width(panel->key[key], 104);
            }
        }

      /* A hold hides every hint but the one being acknowledged, because the
       * gesture in progress is the only thing the keys can do.  A level does
       * the opposite: the user is pressing keys to move it, so the hints are
       * what makes it operable.
       */

      if (snapshot->progress_kind != VS_PROGRESS_NONE &&
          snapshot->progress_kind != VS_PROGRESS_LEVEL &&
          !(snapshot->response_active && snapshot->response_key == key))
        visible = false;

      vs_set_label(panel->key[key], visible ? snapshot->softkey[key].text : "");
      vs_set_text_color(panel->key[key],
          snapshot->softkey[key].highlighted ? vs_rgb(7, 12, 21) :
          vs_rgb(155, 175, 187));"}

{"content":"static void vs_render_content(struct vs_panel_s *panel,
                              const struct vs_ui_snapshot_s *snapshot)
{
  /* The wider upper row carries metadata; the lower row carries the short
   * status moved from the right screen. */

  if (snapshot->page == VS_PAGE_VOLUME)
    {
      lv_obj_set_pos(panel->meta, VS_META_WIDE_X, VS_LOWER_TOP_Y);
      lv_obj_set_width(panel->meta, VS_META_WIDE_WIDTH);
    }
  else
    {
      lv_obj_set_pos(panel->meta, VS_META_X, VS_LOWER_TOP_Y);
      lv_obj_set_width(panel->meta, VS_META_WIDTH);
    }

  vs_set_label(panel->title, snapshot->content_title);
  vs_set_label(panel->body, snapshot->content_body);
  vs_set_label(panel->meta, snapshot->content_meta);
  for (int line = 0; line < 2; line++)
    vs_set_hidden(panel->status_line[line], true);
  if (snapshot->page == VS_PAGE_HISTORY_BLANK)
    {
      char line[VS_TEXT_LONG];

      if (snapshot->network.mode == VS_NET_AP)
        {
          snprintf(line, sizeof(line), "WiFi %s",
                   snapshot->network.ap_client_count != 0 ?
                   "已连接" : "待连接");
        }
      else if (snapshot->network.wifi_issue == VS_WIFI_ISSUE_SSID_NOT_FOUND)
        {
          snprintf(line, sizeof(line), "SSID未扫描到");
        }
      else if (snapshot->network.wifi_issue == VS_WIFI_ISSUE_PASSWORD)
        {
          snprintf(line, sizeof(line), "WiFi密码错误");
        }
      else if (snapshot->network.wifi_issue == VS_WIFI_ISSUE_DISCONNECTED)
        {
          snprintf(line, sizeof(line), "WiFi已断开");
        }
      else
        {
          snprintf(line, sizeof(line), "WiFi %s",
                   snapshot->wifi_ready ? "已连接" : "未连接");
        }
      vs_set_label(panel->status_line[0], line);
      vs_set_hidden(panel->status_line[0], false);
    }
  vs_set_label(panel->status_line[1], snapshot->status_meta);
  vs_set_hidden(panel->status_line[1], snapshot->status_meta[0] == '\0');
  vs_panel_set_progress(panel, snapshot, false);
  vs_panel_set_keys(panel, snapshot, true);
}

static void vs_render_status(struct vs_panel_s *panel,
                             const struct vs_ui_snapshot_s *snapshot)
{
  char value[VS_TEXT_LONG];
  bool progress = snapshot->progress_kind != VS_PROGRESS_NONE &&
                  snapshot->page != VS_PAGE_ERROR;
  bool short_value;

  snprintf(value, sizeof(value), "%s", snapshot->status_value);
  short_value = strlen(value) <= 12;
  if (short_value)
    {
      lv_obj_set_pos(panel->body, VS_STATUS_SHORT_X, VS_STATUS_SHORT_Y);
      lv_obj_set_size(panel->body, VS_STATUS_SHORT_WIDTH,
                      VS_STATUS_SHORT_HEIGHT);
    }
  else
    {
      lv_obj_set_pos(panel->body, VS_STATUS_LONG_X, VS_STATUS_LONG_Y);
      lv_obj_set_size(panel->body, VS_STATUS_LONG_WIDTH,
                      VS_STATUS_LONG_HEIGHT);
    }

  vs_set_label(panel->title, snapshot->status_title);
  vs_set_label(panel->body, value);
  vs_set_label(panel->meta, "");
  vs_set_text_color(panel->body, vs_color(snapshot->emotion_color));
  vs_panel_set_progress(panel, snapshot, progress &&
                        (snapshot->progress_kind == VS_PROGRESS_HOLD ||
                         snapshot->progress_kind == VS_PROGRESS_LEVEL));
  vs_panel_set_keys(panel, snapshot, false);
}

int vs_display_open(struct vs_display_s **display)
{
  struct vs_display_s *state;
  lv_nuttx_dsc_t descriptor;
  int ret;

  if (display == NULL)
    return -EINVAL;

  state = calloc(1, sizeof(*state));
  if (state == NULL)
    return -ENOMEM;

  lv_init();
  lv_nuttx_dsc_init(&descriptor);
  descriptor.fb_path = "/dev/fb0";
  lv_nuttx_init(&descriptor, &state->nuttx);
  if (state->nuttx.disp == NULL)
    {
      free(state);
      return -ENODEV;
    }

  ret = vs_panel_init(&state->panel[VS_STATUS_PANEL], state->nuttx.disp);
  if (ret < 0)
    goto fail_status;

  state->panel[VS_CONTENT_PANEL].display = lv_nuttx_fbdev_create();
  if (state->panel[VS_CONTENT_PANEL].display == NULL ||
      lv_nuttx_fbdev_set_file(state->panel[VS_CONTENT_PANEL].display,
                              "/dev/fb1") < 0)
    {
      ret = -ENODEV;
      goto fail_content;
    }

  ret = vs_panel_init(&state->panel[VS_CONTENT_PANEL],
                      state->panel[VS_CONTENT_PANEL].display);
  if (ret < 0)
    goto fail_content;

  *display = state;
  return 0;

fail_content:
  if (state->panel[VS_CONTENT_PANEL].display != NULL)
    lv_display_delete(state->panel[VS_CONTENT_PANEL].display);
fail_status:
  lv_nuttx_deinit(&state->nuttx);
  free(state);
  return ret;
}

int vs_display_render(struct vs_display_s *display,
                      const struct vs_ui_snapshot_s *snapshot)
{
  bool content_dirty;
  bool status_dirty;

  if (display == NULL || snapshot == NULL)
    return -EINVAL;

  /* fb1 is the physical left content display; fb0 is the physical right
   * status display. */
  content_dirty = !display->previous_valid ||
                  vs_content_changed(snapshot, &display->previous);
  status_dirty = !display->previous_valid ||
                 vs_status_changed(snapshot, &display->previous);
  if (content_dirty)
    vs_render_content(&display->panel[VS_CONTENT_PANEL], snapshot);
  if (status_dirty)
    vs_render_status(&display->panel[VS_STATUS_PANEL], snapshot);

  if (!display->revealed)
    {
      /* Match the old synchronous boot animation's hand-off: both complete
       * frames must reach panel GRAM before the shared backlight is enabled.
       * lv_refr_now() executes each framebuffer's FBIO_UPDATE synchronously. */

      lv_obj_invalidate(display->panel[VS_STATUS_PANEL].screen);
      lv_obj_invalidate(display->panel[VS_CONTENT_PANEL].screen);
      lv_refr_now(display->panel[VS_STATUS_PANEL].display);
      lv_refr_now(display->panel[VS_CONTENT_PANEL].display);
#ifdef CONFIG_LVX_USE_DEMO_CONTEST2026_264_VELASIGHT
      bk7258_display_reveal();
#endif
      display->revealed = true;
    }
  /* After reveal, LVGL's 100 ms display timers coalesce invalidations and cap
   * each panel at 10 FPS.  Only the hidden boot hand-off bypasses that cap. */
  display->previous = *snapshot;
  display->previous_valid = true;
  display->waiting = snapshot->progress_kind == VS_PROGRESS_WAIT;
  snprintf(display->wait_meta, sizeof(display->wait_meta), "%s",
           snapshot->status_meta);
  if (!display->waiting)
    {
      display->wait_phase = 0;
      display->wait_next_ms = 0;
    }
  return 0;
}

void vs_display_tick(struct vs_display_s *display)
{
  if (display != NULL)
    {
      uint32_t now = vs_display_now_ms();

      if (display->waiting &&
          (display->wait_next_ms == 0 ||
           (int32_t)(now - display->wait_next_ms) >= 0))
        {
          static const char *const phases[] = {".", "..", "...", ""};
          char meta[VS_TEXT_LONG];

          snprintf(meta, sizeof(meta), "%s%s", display->wait_meta,
                   phases[display->wait_phase]);
          vs_set_label(display->panel[VS_CONTENT_PANEL].status_line[1],
                       meta);
          display->wait_phase = (display->wait_phase + 1) % 4;
          display->wait_next_ms = now + 350;
        }
      lv_timer_handler();
    }
}

void vs_display_flush(struct vs_display_s *display)
{
  if (display == NULL)
    {
      return;
    }

  /* Both panels, and both synchronously: the two screens carry halves of one
   * message, and lv_refr_now() runs each framebuffer's FBIO_UPDATE before it
   * returns.  This is the same hand-off the boot reveal uses.
   */

  lv_refr_now(display->panel[VS_STATUS_PANEL].display);
  lv_refr_now(display->panel[VS_CONTENT_PANEL].display);
}

void vs_display_close(struct vs_display_s *display)
{
  if (display == NULL)
    return;

  if (display->panel[VS_CONTENT_PANEL].display != NULL)
    lv_display_delete(display->panel[VS_CONTENT_PANEL].display);
  lv_nuttx_deinit(&display->nuttx);
  lv_deinit();
  free(display);
}
"}

{"content":"#  define CONFIG_VS_HISTORY_TTS_DWELL_MS 2000
#endif

/* The status panel's ordinary text colour, and what an emotion colour is
 * measured against.  Same value cloud_classify_emotion() gives a calm frame,
 * so a page reporting calm and a page reporting nothing look alike.
 */

#define VS_COLOR_NEUTRAL 0xe8eef2u

/* How long after a failed STA association the next attempt is made.
 *
 * Every retry is a full scan, authenticate and DHCP cycle on the CP, so the
 * interval is a floor on how often that work is repeated rather than a delay
 * added to it.  Shortened from 20 s to 10 s: the common failure this recovers
 * from is an access point that is not up yet at boot, and 20 s meant a device
 * powered on beside a rebooting router could sit unconnected for most of a
 * minute with nothing on screen to suggest it was still trying.
 */

#define VS_WIFI_RETRY_MS 10000

#define VS_APP_EVENT_QUEUE_SIZE 8

static struct
{
  pthread_mutex_t lock;
  struct vs_app_event_s event[VS_APP_EVENT_QUEUE_SIZE];
  uint8_t read;
  uint8_t write;
  uint8_t count;
} g_app_events =
{
  .lock = PTHREAD_MUTEX_INITIALIZER
};

static struct vs_network_s *g_network_result;
static uint32_t g_active_request_id;

static struct
{
  pthread_mutex_t lock;
  struct vs_input_event_s event[VS_INPUT_EVENT_QUEUE_SIZE];
  uint8_t read;
  uint8_t write;
  uint8_t count;
} g_input_events =
{
  .lock = PTHREAD_MUTEX_INITIALIZER
};

static struct vs_input_s *g_input_worker_state;

static void vs_input_queue_reset(void)
{
  pthread_mutex_lock(&g_input_events.lock);
  g_input_events.read = 0;
  g_input_events.write = 0;
  g_input_events.count = 0;"}

{"content":"struct vs_runtime_s
{
  enum vs_page_e page;
  enum vs_history_view_e view;
  uint16_t index;
  uint8_t progress;
  bool history_blank;
  bool photo_context;
  bool voice_ending;

  /* Volume page state.  volume_level is the ring's 0..100 reading, which is
   * also what gets scaled to the driver's thousandths; volume_editing is
   * whether the browse keys currently move it or still turn pages.
   */

  uint8_t volume_level;
  bool volume_editing;

  /* Set when the level has moved since it was last written.  Volume is saved
   * when the user finishes adjusting rather than on every key press: one
   * completed action is one record, which is how the provisioning store is
   * used too, and it keeps a rename plus a sync off the path of a key the user
   * may be about to press again.
   */

  bool volume_dirty;

  /* A store write waiting for its progress frame to be painted, and the page
   * to return to once it completes.  See vs_request_save().
   */

  bool pending_save;
  enum vs_page_e save_resume_page;

  /* Set from the key press until VS_APP_EVENT_VOICE_LISTENING_READY says the
   * microphone is open.  The listening page shows a preparing state while it
   * is set, so the user is not asked to speak before anything can hear them. */

  bool voice_arming;
  enum vs_page_e social_entry_return_page;
  enum vs_page_e social_exit_return_page;
  enum vs_emotion_e emotion;
  uint32_t emotion_color;
  int error;
  char error_reason[VS_TEXT_LONG];
  bool error_retryable;

  /* What the retry key on the error page means.
   *
   * It used to mean exactly one thing -- re-run the network worker with
   * error_target_mode -- which is why every social failure had to be reported
   * as not retryable: offering the key would have switched the network.  With
   * the kind recorded alongside, a failure can offer a retry that belongs to
   * it.
   */

  enum vs_retry_kind_e error_retry;
  enum vs_net_mode_e error_target_mode;
  enum vs_page_e error_return_page;
  bool network_busy;
  enum vs_net_mode_e network_target_mode;

  /* SoftAP passphrase reset, both halves of it.  ap_reset_holding is the 下一条
   * hold still filling the ring; ap_reset_busy is the AP restart it started.
   * They are separate because the first is cancellable and the second is not,
   * and both are only meaningful on VS_PAGE_SOFTAP.  Kept out of
   * network_busy's way: that one says a worker is running, these say which
   * gesture the page should be describing while it does.
   */

  bool ap_reset_holding;
  bool ap_reset_busy;
  uint32_t wifi_retry_at_ms;
  uint32_t next_request_id;
  uint32_t active_request_id;
  bool api_ready;
  uint32_t response_until_ms;
  enum vs_key_e response_key;
  bool response_pending_visible;
  char response_text[VS_TEXT_SHORT];

  /* Deadline for a social page that is waiting on a worker event, 0 when no
   * such page is showing.  Armed and cleared centrally in the main loop rather
   * than at each transition, so a page added later cannot forget to do it.
   */

  uint32_t social_stage_until_ms;

  /* Which step of a finalize is running, and the line it puts on screen.
   *
   * The stage also chooses the deadline above, which is what turns it from a
   * caption into a hang detector: each step gets a budget sized for that step,
   * and every stage event refreshes it.  One deadline for the whole sequence
   * had to be sized for the sum, which made it useless for catching a single
   * wedged step -- and it fired on a cloud that was merely slow.
   */"}

{"content":"static void vs_snapshot(struct vs_runtime_s *runtime,
                        struct vs_ui_snapshot_s *snapshot)
{
  struct vs_history_index_s current;
  bool have_current;

  have_current = !runtime->history_blank &&
                 vs_history_get_index(VS_HISTORY_KIND_SOCIAL, runtime->index,
                                      &current) == 0;

  memset(snapshot, 0, sizeof(*snapshot));
  snapshot->page = runtime->page;
  snapshot->history_view = runtime->view;
  snapshot->network = runtime->network;
  snapshot->history = NULL;
  snapshot->history_index = runtime->index;
  snapshot->history_count = vs_history_count(VS_HISTORY_KIND_SOCIAL);
  snapshot->history_is_blank = runtime->history_blank;
  snapshot->photo_context = runtime->photo_context;
  snapshot->progress = runtime->progress;
  snapshot->emotion = runtime->emotion;
  snapshot->response_active = runtime->response_until_ms != 0;
  snapshot->response_key = runtime->response_key;
  snapshot->error_retryable = runtime->error_retryable;
  snapshot->wifi_ready = runtime->network.state == VS_NET_STA_READY ||
                         runtime->network.state == VS_NET_AP_READY;
  snapshot->battery_present = false;
  /* UI snapshots are a latency-sensitive hot path.  Never read SD-NAND here;
   * persistent state must be loaded by startup or background event handling. */
  snapshot->api_ready = runtime->api_ready;
  snprintf(snapshot->error_reason, sizeof(snapshot->error_reason), "%s",
           runtime->error_reason);
  /* Only the two pages that are reporting an emotion carry its colour.
   *
   * vs_render_status() paints the status panel's value label with this on every
   * page, and nothing ever put it back.  emotion_color is written when an alert
   * is raised and reset in exactly two places -- a clear, and the start of the
   * next session -- so a session that ended while an alert stood left the
   * finalizing page, the summary and every history entry after it drawing their
   * status text in alert red, until the user happened to start another session.
   *
   * Deciding it here from what the page shows rather than resetting it at each
   * exit is the same choice vs_update_record_audio() makes, and for the same
   * reason: there are six ways out of a session and a reset at each one is six
   * chances to forget.  This way a page that is not about an emotion cannot
   * show one.
   *
   * The runtime fields are still cleared where they should be -- a stale
   * alert_text would otherwise reappear if the page returned to
   * VS_PAGE_SOCIAL_ALERT -- this only stops them reaching the screen from
   * anywhere else.
   */

  snapshot->emotion_color = VS_COLOR_NEUTRAL;

  if (runtime->page == VS_PAGE_SOCIAL_RUNNING ||
      runtime->page == VS_PAGE_SOCIAL_ALERT)
    {
      snapshot->emotion_color = runtime->emotion_color != 0 ?
                        runtime->emotion_color :
                        runtime->emotion == VS_EMOTION_TENSE ? 0xe85d5d :
                        runtime->emotion == VS_EMOTION_CONFUSED ? 0xe3ad4b :
                        runtime->emotion == VS_EMOTION_HAPPY ? 0x48c78e :
                        VS_COLOR_NEUTRAL;
    }

  switch (runtime->page)
    {
      case VS_PAGE_PREPARING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "正在准备");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "VelaSight 即将就绪");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "启动");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "准备中");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "请稍等");
        snapshot->progress_kind = VS_PROGRESS_WAIT;
        break;

      case VS_PAGE_HISTORY:

        /* The left panel's three labels are the only text this page puts on
         * that screen, so "no record" used to mean three empty strings and a
         * screen with nothing but its dividers on it -- while the right screen,
         * whose fields here are constants, looked entirely healthy.
         *
         * Reaching this page without a readable record is a contradiction:
         * vs_browse_page() sends anyone with history_blank set to
         * VS_PAGE_HISTORY_BLANK instead.  It is still worth rendering as words
         * rather than as nothing, because the failure it now describes -- an
         * index that outran the store, or a store that could not be reloaded --
         * is one the user can act on by navigating, and a blank screen is one
         * they can only reboot.
         */

        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "%s", have_current ? current.title : "历史");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "%s", have_current ? current.summary : "记录暂时读不出\n按键翻页重试");
        snprintf(snapshot->content_meta, sizeof(snapshot->content_meta),
                 "%s", have_current ? current.date : "");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "历史");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value),
                 "%02u/%02u", runtime->index + 1,
                 vs_history_count(VS_HISTORY_KIND_SOCIAL));
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta),
                 "已保存");
        vs_key_set(snapshot, VS_KEY_CONFIRM, "询问");
        vs_key_set(snapshot, VS_KEY_BACK, "上一条");
        vs_key_set(snapshot, VS_KEY_NEXT, "下一条");
        break;

      case VS_PAGE_HISTORY_BLANK:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "拍照提问");"}

{"content":"      case VS_PAGE_VOLUME:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "音量");

        /* Middle layer describes what is being set and how loud it now is in
         * words.  It deliberately does not name the keys: the right screen's
         * footer is where key hints belong, and spelling them out in the body
         * duplicated them in a form nobody reads twice.
         */

        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "语音播报\n%s", vs_volume_word(runtime->volume_level));

        /* Lower rows: the address itself on the wider first row, its label on
         * the narrow second row.  The address is the longer meta field that
         * row exists for, and the label fits the four-character limit on the
         * row below it.
         */

        snprintf(snapshot->content_meta, sizeof(snapshot->content_meta),
                 "%s", runtime->network.address);
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "%s",
                 runtime->network.address[0] != '\0' ? "IP地址" : "未联网");

        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "音量");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value),
                 "%u%%", runtime->volume_level);
        snapshot->progress_kind = VS_PROGRESS_LEVEL;
        snapshot->progress = runtime->volume_level;

        /* Next is louder, matching the direction the ring fills and the order
         * the two keys sit in on the footer. */

        if (runtime->volume_editing)
          {
            vs_key_set(snapshot, VS_KEY_CONFIRM, "完成");
            vs_key_set(snapshot, VS_KEY_BACK, "调小");
            vs_key_set(snapshot, VS_KEY_NEXT, "调大");
          }
        else
          {
            vs_key_set(snapshot, VS_KEY_CONFIRM, "调节");
            vs_key_set(snapshot, VS_KEY_BACK, "上一条");
            vs_key_set(snapshot, VS_KEY_NEXT, "下一条");
          }
        break;

      case VS_PAGE_SAVING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "保存设置");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "正在写入");
        snapshot->content_meta[0] = '\0';
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "设置");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value),
                 "保存中");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "请稍等");

        /* No ring: the write is one indivisible operation with no progress to
         * report, and the specification forbids inventing a percentage.  WAIT
         * gives the left footer its dotted animation instead.
         */

        snapshot->progress_kind = VS_PROGRESS_WAIT;
        break;

      case VS_PAGE_SOCIAL_ENTER:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "进入社交");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "继续按住\n松开取消");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "社交");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "%u%%",
                 runtime->progress);
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "按住中");
        snapshot->progress_kind = VS_PROGRESS_HOLD;
        break;

      case VS_PAGE_SOCIAL_STARTING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "启动社交");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "正在建立会话");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "社交");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "连接中");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "请稍等");
        vs_key_set(snapshot, VS_KEY_BACK, "取消");
        break;

      case VS_PAGE_SOCIAL_RUNNING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "社交中");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "继续交流");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "社交中");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value),
                 "%s", runtime->emotion == VS_EMOTION_NONE ? "观察中" :
                  runtime->emotion == VS_EMOTION_TENSE ? "情绪升高" : "观察中");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "采集中");
        vs_key_set(snapshot, VS_KEY_CONFIRM, "暂停");
        vs_key_set(snapshot, VS_KEY_BACK, "按住结束");
        break;

      case VS_PAGE_SOCIAL_ALERT:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "情绪提醒");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body), "%s",
                 runtime->alert_text[0] != '\0' ? runtime->alert_text :
                 "放慢语速\n先听对方说完");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "情绪升高");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "提醒");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "请留意");
        snapshot->emotion = runtime->emotion;
        vs_key_set(snapshot, VS_KEY_CONFIRM, "暂停");
        vs_key_set(snapshot, VS_KEY_BACK, "按住结束");
        break;

      case VS_PAGE_SOCIAL_PAUSING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "正在暂停");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "正在停止采集");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "社交");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "请稍等");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "暂停中");
        snapshot->progress_kind = VS_PROGRESS_WAIT;
        break;

      case VS_PAGE_SOCIAL_PAUSED:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "已暂停");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "准备好后继续");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "社交");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "暂停");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "已暂停");
        vs_key_set(snapshot, VS_KEY_CONFIRM, "继续");
        vs_key_set(snapshot, VS_KEY_BACK, "按住结束");
        break;

      case VS_PAGE_SOCIAL_RESUMING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "正在继续");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "正在恢复采集");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "社交");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "请稍等");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "恢复中");
        snapshot->progress_kind = VS_PROGRESS_WAIT;
        break;

      case VS_PAGE_SOCIAL_EXITING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "结束交流");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                 "继续按住");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "结束");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "%u%%",
                 runtime->progress);
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "按住中");
        snapshot->progress_kind = VS_PROGRESS_HOLD;
        break;

      case VS_PAGE_SOCIAL_FINALIZING:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "整理记录");

        /* The step that is actually running, falling back to the old fixed
         * line only for the window before the first stage event lands.  The
         * page used to say "正在生成建议" for the whole sequence, including
         * while it was stopping the camera and while it was writing to the
         * card -- neither of which is generating anything.
         */

        snprintf(snapshot->content_body, sizeof(snapshot->content_body), "%s",
                 runtime->social_stage_text[0] != '\0' ?
                   runtime->social_stage_text : "正在生成建议");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "整理中");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "处理中");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "请稍等");
        snapshot->progress_kind = VS_PROGRESS_WAIT;
        break;

      case VS_PAGE_SOCIAL_RESULT:
        snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                 "交流摘要");
        snprintf(snapshot->content_body, sizeof(snapshot->content_body), "%s",
                 runtime->result_text[0] != '\0' ? runtime->result_text :
                 "交流记录已整理完成");
        snprintf(snapshot->status_title, sizeof(snapshot->status_title), "结果");
        snprintf(snapshot->status_value, sizeof(snapshot->status_value), "摘要已生成");
        snprintf(snapshot->status_meta, sizeof(snapshot->status_meta), "待播报");
        vs_key_set(snapshot, VS_KEY_BACK, "返回");
        vs_key_set(snapshot, VS_KEY_CONFIRM, "完成");
        break;

      case VS_PAGE_VOICE_LISTENING:
        if (runtime->voice_ending)
          {
            snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                     "正在结束");
            snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                     "保存已完成问答");
            snprintf(snapshot->status_title, sizeof(snapshot->status_title),
                     "会话");
            snprintf(snapshot->status_value, sizeof(snapshot->status_value),
                     "请稍等");
            snprintf(snapshot->status_meta, sizeof(snapshot->status_meta),
                     "写入历史");
            snapshot->progress_kind = VS_PROGRESS_WAIT;
            break;
          }

        if (runtime->voice_arming)
          {
            /* Not listening yet: the round is still loading the referenced
             * record and completing the TLS handshake to the ASR service.
             * Saying "请说话" here would lose the user's opening words. */

            snprintf(snapshot->content_title, sizeof(snapshot->content_title),
                     "正在准备");
            snprintf(snapshot->content_body, sizeof(snapshot->content_body),
                     "连接语音服务\n稍后再说话");
            snprintf(snapshot->status_title, sizeof(snapshot->status_title),
                     "聆听");
            snprintf(snapshot->status_value, sizeof(snapshot->status_value),
                     "准备中");
            snprintf(snapshot->status_meta, sizeof(snapshot->status_meta),
                     "请稍等");
            snapshot->progress_kind = VS_PROGRESS_WAIT;
            vs_key_set(snapshot, VS_KEY_BACK, "退出");
            break;
          }

        /* Pressing 说完 is the way an utterance ends, so the page says so
         * rather than describing a silence timer.  There is no local speech
         * detector any more: an energy threshold miscalibrated for this
