/****************************************************************************
 * Teardown helpers
 ****************************************************************************/

static void social_release_camera(void);
static void social_release_devices(void);
static void social_log_capture_level(void);

/* Stop the producers, join them, and hand the hardware back.  Called on the
 * session thread.
 *
 * The release used to happen much later, in the session worker, after
 * social_finalize_sequence() had returned.  That put the whole tail of a
 * session -- up to a minute of polling for the minutes, the text fetch, the
 * history write, the spoken-minutes download and its playback -- between the
 * last frame anyone wanted and VIDIOC_STREAMOFF.  Nothing was leaking, but
 * the sensor, the YUV block, the JPEG encoder and the DMA channel all kept
 * running at the negotiated rate the entire time, with no consumer: measured
 * 2026-09-07, a session that ended at 10:45:43 was still emitting a frame
 * every 507 ms at 10:47:24, a hundred seconds later, and every one of those
 * frames also cost a console line over the mailbox.  That is CPU taken from
 * the download and the playback that were the only things still working.
 *
 * So the devices go here, at the one moment that is provably safe: both
 * producers have exited, so nothing is going to call grab() or read() again,
 * and the uploader has drained the rings, so nothing still references a frame.
 * The later social_release_devices() calls are idempotent and become no-ops.
 */

static void social_stop_producers(void)
{
  pthread_mutex_lock(&g_social.lock);
  g_social.stop_capture = true;
  g_social.paused       = false;
  pthread_cond_broadcast(&g_social.cond);"}

{"content":"static void cloud_classify_emotion(const char *color, const char *detail,
                                   enum vs_emotion_e *emotion, uint32_t *rgb,
                                   bool *extreme)
{
  *emotion = VS_EMOTION_NONE;
  *rgb = 0xe8eef2;

  /* Independent of the colour branches below, and deliberately evaluated
   * before them so it is obvious that no branch sets it.
   */

  *extreme = detail != NULL &&
             (strstr(detail, "生气") != NULL ||
              strstr(detail, "伤心") != NULL);

  if (color == NULL)
    {
      return;
    }

  if (strcasecmp(color, "red") == 0)
    {
      *emotion = VS_EMOTION_TENSE;
      *rgb = 0xe85d5d;
    }
  else if (strcasecmp(color, "blue") == 0)
    {
      *emotion = VS_EMOTION_CONFUSED;
      *rgb = 0x5d8fe8;
    }
  else if (strcasecmp(color, "green") == 0)
    {
      if (detail != NULL && strstr(detail, "愉悦") != NULL)
        {
          *emotion = VS_EMOTION_HAPPY;
          *rgb = 0x48c78e;
        }
      else
        {
          *emotion = VS_EMOTION_CALM;
          *rgb = 0xe8eef2;
        }
    }
}

/****************************************************************************
 * Name: cloud_check_envelope
 *
 * Description:
 *   Validate the parts every /contest/v1 response shares and hand back the
 *   "value" member.
 *
 *   The sessionId echo is checked rather than trusted.  One deviceId may only
 *   have one live session, and the cloud replaces an old session with a newer
 *   one, so a reply carrying a different sessionId means this session has
 *   already been superseded -- continuing to feed it frames would attribute
 *   them to a session that no longer exists.
 *
 * Returned Value:
 *   0 with *status and *value filled, or a negative errno.
 *
 ****************************************************************************/

static int cloud_check_envelope(cJSON *root, const char *session_id,
                                int *status, cJSON **value)
{
  char echoed[VS_CLOUD_SESSION_ID_MAX];

  if (root == NULL || !cJSON_IsObject(root))
    {
      return -EPROTO;
    }

  if (!cloud_json_int(root, "status", status))
    {
      printf("%s: response has no status\n", CLOUD_TAG);
      return -EPROTO;
    }

  if (session_id != NULL &&
      cloud_json_exact(root, "sessionId", echoed, sizeof(echoed)) &&
      echoed[0] != '\0' && strcmp(echoed, session_id) != 0)
    {
      printf("%s: session mismatch, sent %s got %s\n", CLOUD_TAG,
             session_id, echoed);
      return -ESTALE;
    }

  *value = cJSON_GetObjectItem(root, "value");
  return 0;
}

