  unsigned int day;
  unsigned int hour;
  unsigned int minute;
  unsigned int second;
  unsigned int month;
  int year;

  if (sscanf(value, "%*3s, %u %3s %d %u:%u:%u", &day, month_name, &year,
             &hour, &minute, &second) != 6)
    {
